void logToFile(const String &level, const String &msg) {
  if (!systemLogEnabled || !sdReady) return;
  if (getLogLevelValue(level) > systemLogLevel) return;
  if (xSemaphoreTake(sdMutex, pdMS_TO_TICKS(500)) != pdTRUE) return;
  if (!SD.exists("/logs")) SD.mkdir("/logs");
  String path = getMonthlyLogPath();
  File f = SD.open(path, FILE_APPEND);
  if (f) {
