String formatWeight(float grams) {
  if (weightUnit == UNIT_GRAM) return String(grams, 1) + " g";
  else if (weightUnit == UNIT_KILOGRAM) return String(grams / 1000.0, 3) + " kg";
  else return (abs(grams) < 1000.0) ? String(grams, 1) + " g" : String(grams / 1000.0, 3) + " kg";
}

float getWeightValue(float grams) {
  if (weightUnit == UNIT_GRAM) return grams;
  if (weightUnit == UNIT_KILOGRAM) return grams / 1000.0;
  return (abs(grams) < 1000.0) ? grams : grams / 1000.0;
}

String getWeightUnitStr() {
  if (weightUnit == UNIT_GRAM) return "g";
  if (weightUnit == UNIT_KILOGRAM) return "kg";
  return (abs(currentWeightGrams) < 1000.0) ? "g" : "kg";
}

int getWeightDecimals() {
  if (weightUnit == UNIT_GRAM) return 1;
  if (weightUnit == UNIT_KILOGRAM) return 3;
  return (abs(currentWeightGrams) < 1000.0) ? 1 : 3;
}

// ============================================================
// ========== Weight Algorithms ============
// ============================================================

float algoRaw(float s) { return s; }

float algoAvg10() {
  if (weightBufferCount < 1) return 0;
  int n = min(10, weightBufferCount);
  float sum = 0;
  for (int i = 0; i < n; i++) {
    int idx = (weightBufferIdx - 1 - i + WBUF_SIZE) % WBUF_SIZE;
    sum += weightBuffer[idx];
  }
  return sum / n;
}

float algoAvg20() {
  if (weightBufferCount < 1) return 0;
  int n = min(20, weightBufferCount);
  float sum = 0;
  for (int i = 0; i < n; i++) {
    int idx = (weightBufferIdx - 1 - i + WBUF_SIZE) % WBUF_SIZE;
    sum += weightBuffer[idx];
  }
  return sum / n;
}

float algoMedian() {
  if (weightBufferCount < 5) return algoAvg10();
  float buf[5];
  for (int i = 0; i < 5; i++) {
    int idx = (weightBufferIdx - 1 - i + WBUF_SIZE) % WBUF_SIZE;
    buf[i] = weightBuffer[idx];
  }
  for (int i = 0; i < 4; i++)
    for (int j = 0; j < 4 - i; j++)
      if (buf[j] > buf[j + 1]) { float t = buf[j]; buf[j] = buf[j + 1]; buf[j + 1] = t; }
  return buf[2];
}

float algoTrimmed() {
  if (weightBufferCount < 10) return algoAvg10();
  int n = min(20, weightBufferCount);
  float sorted[20];
  for (int i = 0; i < n; i++) {
    int idx = (weightBufferIdx - 1 - i + WBUF_SIZE) % WBUF_SIZE;
    sorted[i] = weightBuffer[idx];
  }
  for (int i = 0; i < n - 1; i++)
    for (int j = 0; j < n - i - 1; j++)
      if (sorted[j] > sorted[j + 1]) { float t = sorted[j]; sorted[j] = sorted[j + 1]; sorted[j + 1] = t; }
  int trim = n / 10;
  if (trim < 1) trim = 1;
  float sum = 0;
  int cnt = 0;
  for (int i = trim; i < n - trim; i++) { sum += sorted[i]; cnt++; }
  return sum / cnt;
}

float algoEMA(float s) {
  if (!weightFilterInit) { kalmanX = s; weightFilterInit = true; return s; }
  kalmanX = emaAlpha * s + (1.0f - emaAlpha) * kalmanX;
  return kalmanX;
}

float algoTrimmedEMA(float s) {
  float trimmed = algoTrimmed();
  if (!weightFilterInit) { kalmanX = trimmed; weightFilterInit = true; return trimmed; }
  kalmanX = emaAlpha * trimmed + (1.0f - emaAlpha) * kalmanX;
  return kalmanX;
}

float algoKalman(float s) {
  if (!weightFilterInit) { kalmanX = s; weightFilterInit = true; return s; }
  kalmanP += kalmanQ;
  float K = kalmanP / (kalmanP + kalmanR);
  kalmanX = kalmanX + K * (s - kalmanX);
  kalmanP = (1 - K) * kalmanP;
  return kalmanX;
}

float algoMoving() { return algoAvg10(); }

float algoHybrid(float s) {
  if (!weightFilterInit) { kalmanX = s; weightFilterInit = true; return s; }
  float diff = abs(s - kalmanX);
  if (diff > 50.0) kalmanX = kalmanX * 0.2 + s * 0.8;
  else if (diff > 5.0) kalmanX = kalmanX * 0.5 + s * 0.5;
  else kalmanX = kalmanX * 0.9 + s * 0.1;
  return kalmanX;
}

float processWeight(float newSample) {
  float result;
  switch (currentAlgo) {
    case ALGO_RAW:         result = algoRaw(newSample); break;
    case ALGO_AVG10:       result = algoAvg10(); break;
    case ALGO_AVG20:       result = algoAvg20(); break;
    case ALGO_MEDIAN:      result = algoMedian(); break;
    case ALGO_TRIMMED:     result = algoTrimmed(); break;
    case ALGO_EMA:         result = algoEMA(newSample); break;
    case ALGO_TRIMMED_EMA: result = algoTrimmedEMA(newSample); break;
    case ALGO_KALMAN:      result = algoKalman(newSample); break;
    case ALGO_MOVING:      result = algoMoving(); break;
    case ALGO_HYBRID:      result = algoHybrid(newSample); break;
    default:               result = algoTrimmedEMA(newSample); break;
  }
  if (abs(result) < 0.5) result = 0.0;
  return result;
}

void sampleWeightFast() {
  if (!hx711Ready) return;
  if (!scale.wait_ready_timeout(5)) return;
  long raw = scale.read();
  currentRaw = raw;
  float grams = (raw - hx711Offset) / hx711Factor;
  weightBuffer[weightBufferIdx] = grams;
  weightBufferIdx = (weightBufferIdx + 1) % WBUF_SIZE;
  if (weightBufferCount < WBUF_SIZE) weightBufferCount++;
  currentWeightGrams = processWeight(grams);
}

void resetWeightFilter() {
  weightFilterInit = false;
  weightBufferCount = 0;
  weightBufferIdx = 0;
  kalmanX = 0.0;
  kalmanP = 1.0;
  currentWeightGrams = 0.0;
}

