// ========== JDN - تبدیل دقیق شمسی ↔ میلادی ==========
// ============================================================

void jalaliToGregorian(int jy, int jm, int jd, int &gy, int &gm, int &gd) {
  int jy2 = jy - 979;
  int jm2 = jm - 1;
  int jd2 = jd - 1;
  long j_day_no = 365L * jy2 + (jy2 / 33) * 8 + ((jy2 % 33) + 3) / 4;
  for (int i = 0; i < jm2; i++) j_day_no += (i < 6) ? 31 : 30;
  j_day_no += jd2;
  long g_day_no = j_day_no + 79;
  long gy2 = 1600 + 400 * (g_day_no / 146097);
  g_day_no = g_day_no % 146097;
  bool leap = true;
  if (g_day_no >= 36525) {
    g_day_no--;
    gy2 += 100 * (g_day_no / 36524);
    g_day_no = g_day_no % 36524;
    if (g_day_no >= 365) g_day_no++;
    else leap = false;
  }
  gy2 += 4 * (g_day_no / 1461);
  g_day_no %= 1461;
  if (g_day_no >= 366) {
    leap = false;
    g_day_no--;
    gy2 += g_day_no / 365;
    g_day_no = g_day_no % 365;
  }
  gd = g_day_no + 1;
  static const int g_days_in_month[] = {31,28,31,30,31,30,31,31,30,31,30,31};
  int i;
  for (i = 0; i < 12 && gd > g_days_in_month[i] + ((i == 1 && leap) ? 1 : 0); i++) {
    gd -= g_days_in_month[i] + ((i == 1 && leap) ? 1 : 0);
  }
  gy = gy2;
  gm = i + 1;
}

// ============================================================
// ========== زمان ============
// ============================================================

uint32_t daysFromCivil(int y, unsigned m, unsigned d) {
  y -= m <= 2;
  const int era = (y >= 0 ? y : y - 399) / 400;
  const unsigned yoe = (unsigned)(y - era * 400);
  const unsigned doy = (153 * (m + (m > 2 ? -3 : 9)) + 2) / 5 + d - 1;
  const unsigned doe = yoe * 365 + yoe / 4 - yoe / 100 + doy;
  return era * 146097 + (int)doe - 719468;
}

uint32_t makeEpoch(int y, int mo, int d, int h, int mi, int s) {
  int64_t days = daysFromCivil(y, mo, d);
  int64_t v = days * 86400LL + h * 3600 + mi * 60 + s;
  if (v < 0) return 0;
  return (uint32_t)v;
}

uint32_t currentEpoch() {
