String twoDigits(int n) { return (n < 10) ? "0" + String(n) : String(n); }

void epochToDate(uint32_t epoch, int &year, int &month, int &day,
                 int &hour, int &minute, int &second) {
  uint32_t days = epoch / 86400UL;
  uint32_t rem = epoch % 86400UL;
  hour = rem / 3600UL; rem %= 3600UL;
  minute = rem / 60UL; second = rem % 60UL;
  int y = 1970;
  while (true) {
    bool leap = ((y % 4 == 0 && y % 100 != 0) || (y % 400 == 0));
    int dy = leap ? 366 : 365;
    if (days >= (uint32_t)dy) { days -= dy; y++; } else break;
  }
  static const int md[] = {31,28,31,30,31,30,31,31,30,31,30,31};
  month = 1;
  while (month <= 12) {
    int dm = md[month - 1];
    if (month == 2 && ((y % 4 == 0 && y % 100 != 0) || (y % 400 == 0))) dm = 29;
    if (days >= (uint32_t)dm) { days -= dm; month++; } else break;
  }
  year = y; day = days + 1;
}

void gregorianToJalali(int gy, int gm, int gd, int &jy, int &jm, int &jd) {
  static const int g_d_m[] = {0,31,59,90,120,151,181,212,243,273,304,334};
  int gy2 = (gm > 2) ? (gy + 1) : gy;
  long days = 355666 + (365L * gy) + ((gy2 + 3) / 4) - ((gy2 + 99) / 100) +
              ((gy2 + 399) / 400) + gd + g_d_m[gm - 1];
  jy = -1595 + (33 * (days / 12053));
  days %= 12053;
  jy += 4 * (days / 1461);
  days %= 1461;
  if (days > 365) {
    jy += (days - 1) / 365;
    days = (days - 1) % 365;
  }
  if (days < 186) {
    jm = 1 + (days / 31);
    jd = 1 + (days % 31);
  } else {
    jm = 7 + ((days - 186) / 30);
    jd = 1 + ((days - 186) % 30);
  }
}

String getShamsiDate() {
  if (!timeReady) return "no-date";
  int y, mo, d, h, mi, s;
  epochToDate(currentEpoch(), y, mo, d, h, mi, s);
  int jy, jm, jd;
  gregorianToJalali(y, mo, d, jy, jm, jd);
  return String(jy) + "/" + twoDigits(jm) + "/" + twoDigits(jd);
}

