// ========== NTP ============
// ============================================================

unsigned long getNTPTime() {
  byte pb[48];
  for (int i = 0; i < 4; i++) {
    memset(pb, 0, 48);
    pb[0] = 0b11100011; pb[2] = 6; pb[3] = 0xEC;
    pb[12] = 49; pb[13] = 0x4E; pb[14] = 49; pb[15] = 52;
    ntpUDP.stop(); delay(100);
    if (!ntpUDP.begin(123)) continue;
    ntpUDP.beginPacket(ntpServers[i], 123);
    ntpUDP.write(pb, 48);
    ntpUDP.endPacket();
    unsigned long to = millis() + 5000;
    while (millis() < to) {
      if (ntpUDP.parsePacket()) {
        ntpUDP.read(pb, 48);
        unsigned long hw = word(pb[40], pb[41]);
        unsigned long lw = word(pb[42], pb[43]);
        unsigned long secs = hw << 16 | lw;
        ntpUDP.stop();
        return secs - 2208988800UL;
      }
      delay(200);
    }
    ntpUDP.stop();
  }
  return 0;
}

bool syncTimeFromNTP() {
  if (!wifiConnected) return false;
  logMsg("NTP sync...");
  unsigned long epoch = getNTPTime();
  if (epoch) {
    savedEpoch = epoch + TIMEZONE_OFFSET_SEC;
    epochBaseMillis = millis();
    timeReady = true;
    logMsg("NTP OK: " + getShamsiDate() + " " + getShamsiTime());
    return true;
  }
  logWarn("NTP FAILED");
  return false;
}
