void setupServo() {
  logMsg("========== SERVO 180 INIT ==========");
  myservo.setPeriodHertz(50);
  myservo.attach(SERVO_PIN, SERVO_MIN_US, SERVO_MAX_US);
  servoAttached = true;
  myservo.write(90);
  servoAngle = 90;
  delay(500);
  logMsg("Servo 180 OK (GPIO " + String(SERVO_PIN) + ")");
}

bool setServoAngle(int angle) {
  if (!servoEnabled || !servoAttached) return false;
  if (angle < servoMin || angle > servoMax) return false;
  if (xSemaphoreTake(servoMutex, pdMS_TO_TICKS(500)) != pdTRUE) return false;
  myservo.write(angle);
  servoAngle = angle;
  xSemaphoreGive(servoMutex);
  return true;
}

void servoPreset(String preset) {
  preset.toLowerCase();
  preset.trim();
  if (preset == "open") setServoAngle(servoMax);
  else if (preset == "close") setServoAngle(servoMin);
  else if (preset == "half" || preset == "center") setServoAngle(90);
  else if (preset == "wave") {
    for (int i = 0; i < 3; i++) {
      for (int a = 40; a <= 140; a += 5) { setServoAngle(a); delay(20); }
      for (int a = 140; a >= 40; a -= 5) { setServoAngle(a); delay(20); }
    }
    setServoAngle(90);
  }
  else if (preset == "nod") {
    for (int i = 0; i < 3; i++) {
      setServoAngle(60); delay(400);
      setServoAngle(120); delay(400);
    }
    setServoAngle(90);
  }
  else if (preset == "shake") {
    for (int i = 0; i < 5; i++) {
      setServoAngle(30); delay(150);
      setServoAngle(150); delay(150);
    }
    setServoAngle(90);
  }
  else if (preset == "scan") {
    for (int a = servoMin; a <= servoMax; a += 2) { setServoAngle(a); delay(30); }
    for (int a = servoMax; a >= servoMin; a -= 2) { setServoAngle(a); delay(30); }
    setServoAngle(90);
  }
  else if (preset == "step") {
    int steps[] = {0, 45, 90, 135, 180, 135, 90, 45, 0};
    for (int i = 0; i < 9; i++) { setServoAngle(steps[i]); delay(300); }
    setServoAngle(90);
  }
  else if (preset == "breathe") {
    for (int i = 0; i < 3; i++) {
      for (int a = 60; a <= 120; a++) { setServoAngle(a); delay(15); }
      for (int a = 120; a >= 60; a--) { setServoAngle(a); delay(15); }
    }
    setServoAngle(90);
  }
  else if (preset == "random") {
    for (int i = 0; i < 10; i++) {
      setServoAngle(random(servoMin, servoMax + 1));
      delay(random(200, 600));
    }
    setServoAngle(90);
  }
  else if (preset == "sweep") {
    for (int a = servoMin; a <= servoMax; a += 10) { setServoAngle(a); delay(80); }
    for (int a = servoMax; a >= servoMin; a -= 10) { setServoAngle(a); delay(80); }
    setServoAngle(90);
  }
  else if (preset == "toggle") {
    if (servoAngle < 90) setServoAngle(servoMax);
    else setServoAngle(servoMin);
  }
}

// ============================================================
// ========== Servo 360 (MG946R) ==========
// ============================================================

int getRampStep() {
  if (currentRamp == RAMP_CUSTOM) return customRampStep;
  switch (currentRamp) {
    case RAMP_INSTANT: return 100;
    case RAMP_FAST: return 10;
    case RAMP_NORMAL: return 5;
    case RAMP_SMOOTH: return 2;
    case RAMP_VERY_SMOOTH: return 1;
    default: return 5;
  }
}

int getRampDelay() {
  if (currentRamp == RAMP_CUSTOM) return customRampDelay;
  switch (currentRamp) {
    case RAMP_INSTANT: return 0;
    case RAMP_FAST: return 20;
    case RAMP_NORMAL: return 25;
    case RAMP_SMOOTH: return 30;
    case RAMP_VERY_SMOOTH: return 30;
    default: return 25;
  }
}

String getRampName() {
  switch (currentRamp) {
    case RAMP_INSTANT: return "INSTANT";
    case RAMP_FAST: return "FAST";
    case RAMP_NORMAL: return "NORMAL";
    case RAMP_SMOOTH: return "SMOOTH";
    case RAMP_VERY_SMOOTH: return "VERY_SMOOTH";
    case RAMP_CUSTOM: return "CUSTOM";
  }
  return "?";
}

int servo360SpeedToPulse(int speed) {
  speed = constrain(speed, -100, 100);
  if (speed == 0) return SERVO360_CENTER;
  if (speed > 0) return map(speed, 0, 100, SERVO360_CENTER + 20, SERVO360_MAX_PULSE);
  return map(speed, -100, 0, SERVO360_MIN_PULSE, SERVO360_CENTER - 20);
}

void servo360WritePulse(int pulse) {
  if (!servo360Enabled) return;
  pulse = constrain(pulse, SERVO360_MIN_PULSE, SERVO360_MAX_PULSE);
  myservo360.writeMicroseconds(pulse);
}

void setupServo360() {
  logMsg("========== SERVO 360 INIT ==========");
  myservo360.setPeriodHertz(50);
  myservo360.attach(SERVO360_PIN, SERVO360_MIN_PULSE, SERVO360_MAX_PULSE);
  myservo360.writeMicroseconds(SERVO360_CENTER);
  servo360Speed = 0;
  servo360Target = 0;
  delay(500);
  logMsg("Servo 360 OK (GPIO " + String(SERVO360_PIN) + ")");
}

void setServo360Speed(int target) {
  if (!servo360Enabled) return;
  target = constrain(target, -100, 100);

  if (xSemaphoreTake(servo360Mutex, pdMS_TO_TICKS(100)) != pdTRUE) return;

  if (abs(target - servo360Speed) < getRampStep()) {
    servo360Speed = target;
    servo360WritePulse(servo360SpeedToPulse(servo360Speed));
    servo360Ramping = false;
    xSemaphoreGive(servo360Mutex);
    return;
  }

  servo360Target = target;
  servo360Ramping = true;
  xSemaphoreGive(servo360Mutex);
}

void stopServo360Immediate() {
  if (xSemaphoreTake(servo360Mutex, pdMS_TO_TICKS(100)) != pdTRUE) return;
  servo360Ramping = false;
  servo360Turning = false;
  servo360Target = 0;
  servo360Speed = 0;
  servo360WritePulse(SERVO360_CENTER);
  xSemaphoreGive(servo360Mutex);
  logMsg("Servo360: EMERGENCY STOP");
}

void stopServo360Soft() {
  servo360Turning = false;
  setServo360Speed(0);
}

void startServo360Turns(float revolutions, int speedPercent) {
  if (!servo360Enabled) return;
  if (revolutions == 0) return;

  int absSpeed = constrain(abs(speedPercent), 10, 100);
  int direction = (speedPercent >= 0) ? 1 : -1;

  float oneRevMs = SERVO360_FULL_REV_MS * 100.0 / absSpeed;
  oneRevMs /= turnCalibration;

  unsigned long totalMs = (unsigned long)(oneRevMs * abs(revolutions));

  servo360TurnStart = millis();
  servo360TurnDuration = totalMs;
  servo360Turning = true;
  servo360TurnSpeed = direction * absSpeed;

  setServo360Speed(servo360TurnSpeed);

  logMsg("Servo360: " + String(revolutions) + " rev @ " + String(absSpeed) + "% = " + String(totalMs / 1000.0, 1) + "s");
}

void checkServo360TurnComplete() {
  if (!servo360Turning) return;
  if (millis() - servo360TurnStart >= servo360TurnDuration) {
    servo360Turning = false;
    setServo360Speed(0);
    logMsg("Servo360: turn complete");
  }
}

float getServo360Progress() {
  if (!servo360Turning) return 0;
  unsigned long elapsed = millis() - servo360TurnStart;
  if (elapsed >= servo360TurnDuration) return 1.0;
  return (float)elapsed / servo360TurnDuration;
}

void TaskServo360Code(void *pvParameters) {
  logMsg("TaskServo360 started");
  while (true) {
    if (servo360Ramping && servo360Enabled) {
      if (xSemaphoreTake(servo360Mutex, pdMS_TO_TICKS(50)) == pdTRUE) {
        int step = getRampStep();
        int diff = servo360Target - servo360Speed;

        if (abs(diff) <= step) {
          servo360Speed = servo360Target;
          servo360WritePulse(servo360SpeedToPulse(servo360Speed));
          servo360Ramping = false;
        } else {
          if (diff > 0) servo360Speed += step;
          else servo360Speed -= step;
          servo360WritePulse(servo360SpeedToPulse(servo360Speed));
        }
        xSemaphoreGive(servo360Mutex);
      }
    }
    checkServo360TurnComplete();
    delay(getRampDelay());
  }
}

