// ========== I2C ============
// ============================================================

void scanI2C(TwoWire &bus, String name) {
  int nDevices = 0;
  logMsg("Scanning " + name + "...");
  for (byte addr = 1; addr < 127; addr++) {
    bus.beginTransmission(addr);
    if (bus.endTransmission() == 0) {
      nDevices++;
      logMsg("  Found 0x" + String(addr, HEX));
    }
  }
  if (nDevices == 0) logWarn("  No devices");
}

void resetAHT20() {
  Wire1.beginTransmission(0x38);
  Wire1.write(0xBA);
  Wire1.endTransmission();
  delay(30);
  Wire1.beginTransmission(0x38);
  Wire1.write(0xBE);
  Wire1.write(0x08);
  Wire1.write(0x00);
  Wire1.endTransmission();
  delay(20);
}

bool tryInitAHT10() {
  if (aht10Ready) return true;
  Wire.beginTransmission(0x38);
  if (Wire.endTransmission() != 0) return false;
  delay(50);
  if (aht10.begin(&Wire)) { aht10Ready = true; return true; }
  return false;
}

bool tryInitAHT20() {
  if (aht20Ready) return true;
  Wire1.beginTransmission(0x38);
  if (Wire1.endTransmission() != 0) return false;
  delay(50);
  if (aht20.begin(&Wire1)) { aht20Ready = true; return true; }
  resetAHT20();
  delay(200);
  if (aht20.begin(&Wire1)) { aht20Ready = true; return true; }
  return false;
}

bool tryInitOLED() {
  if (oledReady) return true;
  Wire.beginTransmission(0x3C);
  if (Wire.endTransmission() != 0) return false;
  oled.setI2CAddress(0x3C * 2);
  oled.begin();
  oled.setContrast(200);
  oledReady = true;
  return true;
}

void checkI2CDevices() {
  if (aht10Ready) {
    Wire.beginTransmission(0x38);
    if (Wire.endTransmission() != 0) { aht10Ready = false; aht10Temp = NAN; aht10Hum = NAN; }
  } else tryInitAHT10();
  if (aht20Ready) {
    Wire1.beginTransmission(0x38);
    if (Wire1.endTransmission() != 0) { aht20Ready = false; aht20Temp = NAN; aht20Hum = NAN; }
  } else tryInitAHT20();
  if (oledReady) {
    Wire.beginTransmission(0x3C);
    if (Wire.endTransmission() != 0) oledReady = false;
  } else tryInitOLED();
}

void setupI2C() {
  logMsg("========== I2C INIT ==========");
  Wire.begin(I2C0_SDA, I2C0_SCL);
  Wire.setClock(100000);
  delay(100);
  scanI2C(Wire, "Bus 0");
  if (aht10.begin(&Wire)) { aht10Ready = true; logMsg("AHT10 OK"); }
  oled.setI2CAddress(0x3C * 2);
  oled.begin();
  oled.setContrast(200);
  oled.clearBuffer();
  oled.setFont(u8g2_font_6x10_tf);
  oled.drawStr(0, 12, "ESP32-S3 v10.7");
  oled.drawStr(0, 24, "Booting...");
  oled.sendBuffer();
  oledReady = true;
  Wire1.begin(I2C1_SDA, I2C1_SCL);
  Wire1.setClock(100000);
  delay(200);
  scanI2C(Wire1, "Bus 1");
  aht20Ready = false;
  for (int attempt = 0; attempt < 3; attempt++) {
    if (aht20.begin(&Wire1)) { aht20Ready = true; break; }
    resetAHT20();
    delay(200);
  }
}

void readAHT() {
  if (xSemaphoreTake(i2cMutex, pdMS_TO_TICKS(500)) != pdTRUE) return;
  if (aht10Ready) {
    sensors_event_t h, t;
    if (aht10.getEvent(&h, &t)) {
      aht10Temp = t.temperature;
      aht10Hum = h.relative_humidity + aht10HumOffset;
      if (aht10Hum < 0) aht10Hum = 0;
      if (aht10Hum > 100) aht10Hum = 100;
    }
  }
  if (aht20Ready) {
    sensors_event_t h, t;
    if (aht20.getEvent(&h, &t)) {
      aht20Temp = t.temperature;
      aht20Hum = h.relative_humidity + aht20HumOffset;
      if (aht20Hum < 0) aht20Hum = 0;
      if (aht20Hum > 100) aht20Hum = 100;
    }
  }
  xSemaphoreGive(i2cMutex);
}

