// ============================================================
// ========== PUMP R385 (D4184) - توابع اصلی ==========
// ============================================================

void setupPump() {
  logMsg("========== PUMP R385 INIT ==========");
  // API جدید ESP32 Core 3.x
  ledcAttach(PUMP_PWM_PIN, PUMP_PWM_FREQ, PUMP_PWM_RES);
  ledcWrite(PUMP_PWM_PIN, 0);
  pumpCurrentSpeed = 0;
  pumpRunning = false;
  logMsg("Pump PWM OK (GPIO " + String(PUMP_PWM_PIN) + ")");
}

void pumpSetSpeed(int percent) {
  percent = constrain(percent, 0, 100);
  if (xSemaphoreTake(pumpMutex, pdMS_TO_TICKS(100)) != pdTRUE) return;
  int duty = map(percent, 0, 100, 0, 255);
  ledcWrite(PUMP_PWM_PIN, duty);
  pumpCurrentSpeed = percent;
  pumpRunning = (percent > 0);
  xSemaphoreGive(pumpMutex);
}

void pumpOff() {
  pumpSetSpeed(0);
  pumpManualMode = false;
  pumpManualTimedActive = false;
  logMsg("Pump OFF");
}

void pumpOn(int speed) {
  pumpSetSpeed(speed);
  logMsg("Pump ON @" + String(speed) + "%");
}

void pumpInitAllTimers() {
  for (int i = 0; i < MAX_PUMP_TIMERS; i++) {
    pumpTimers[i].enabled = false;
    pumpTimers[i].startHour = 0;
    pumpTimers[i].startMinute = 0;
    pumpTimers[i].durationSec = 0;
    pumpTimers[i].speed = 0;
    pumpTimers[i].repeatMode = PUMP_REPEAT_ONCE;
    pumpTimers[i].source = PUMP_SRC_NONE;
    pumpTimers[i].isRunning = false;
    pumpTimers[i].startTime = 0;
    pumpTimers[i].executedToday = false;
    pumpTimers[i].lastExecDayKey = -1;
  }
}

// ============================================================
// ========== PUMP Timers - منطق اصلی ==========
// ============================================================

void pumpTimerStart(int slot) {
  if (slot < 0 || slot >= MAX_PUMP_TIMERS) return;
  PumpTimer &t = pumpTimers[slot];
  if (!t.enabled) return;
  if (t.speed <= 0 || t.speed > 100) return;
  if (t.isRunning) return;
  t.isRunning = true;
  t.startTime = millis();
  pumpOn(t.speed);
  String src = (t.source == PUMP_SRC_SMS) ? "SMS" : "WEB";
  logMsg("Pump Timer #" + String(slot + 1) + " START (" + src + ") @" + String(t.speed) + "% for " + String(t.durationSec) + "s");
  String msg = "Pump ON Timer #" + String(slot + 1) + "\n";
  msg += "Speed: " + String(t.speed) + "%\n";
  msg += "Duration: " + String(t.durationSec) + "s\n";
  msg += "Source: " + src;
  if (gsmReady && gsmRegistered) sendSMS(authorizedNumber, msg);
}

void pumpTimerStop(int slot, bool sendSmsFlag = true) {
  if (slot < 0 || slot >= MAX_PUMP_TIMERS) return;
  PumpTimer &t = pumpTimers[slot];
  if (!t.isRunning) return;
  t.isRunning = false;
  pumpOff();
  logMsg("Pump Timer #" + String(slot + 1) + " STOP");
  if (t.repeatMode == PUMP_REPEAT_ONCE) {
    t.enabled = false;
    t.executedToday = true;
    savePumpTimers();
    logMsg("Pump Timer #" + String(slot + 1) + " disabled (once)");
  }
  if (sendSmsFlag) {
    String src = (t.source == PUMP_SRC_SMS) ? "SMS" : "WEB";
    String msg = "Pump OFF Timer #" + String(slot + 1) + " (" + src + ")";
    if (gsmReady && gsmRegistered) sendSMS(authorizedNumber, msg);
  }
}

int getDayKey(int year, int month, int day) {
  return year * 10000 + month * 100 + day;
}

void pumpTimersCheck() {
  if (!timeReady) return;
  if (!taskStatus.pumpEnabled) return;
  int y, mo, d, h, mi, s;
  epochToDate(currentEpoch(), y, mo, d, h, mi, s);
  int dayKey = getDayKey(y, mo, d);

  for (int i = 0; i < MAX_PUMP_TIMERS; i++) {
    PumpTimer &t = pumpTimers[i];

    // چک پایان تایمر در حال اجرا
    if (t.isRunning) {
      if (millis() - t.startTime >= (unsigned long)t.durationSec * 1000UL) {
        pumpTimerStop(i, true);
      }
      continue;
    }

    if (!t.enabled) continue;
    if (t.durationSec <= 0) continue;

    // ریست روز جدید برای daily
    if (t.repeatMode == PUMP_REPEAT_DAILY && t.lastExecDayKey != dayKey) {
      t.executedToday = false;
    }

    // چک زمان شروع
    if (!t.executedToday && h == t.startHour && mi == t.startMinute) {
      if (s < 5) {
        t.lastExecDayKey = dayKey;
        t.executedToday = true;
        pumpTimerStart(i);
      }
    }
  }

  // چک پایان دستی زمان‌دار
    if (pumpManualTimedActive) {
    if (millis() - pumpManualTimedStartMs >= pumpManualTimedDuration) {   // ← تغییر نام
      pumpManualTimedActive = false;
      pumpOff();
      logMsg("Pump manual-timed complete");
    }
  }
}

void TaskPumpCode(void *pvParameters) {
  logMsg("TaskPump started");
  unsigned long lastCheck = 0;
  while (true) {
    if (millis() - lastCheck >= PUMP_TIMER_CHECK_INTERVAL) {
      lastCheck = millis();
      pumpTimersCheck();
    }
    delay(200);
  }
}

void pumpManualTimedStart(int speed, int durationSec) {
  if (speed <= 0 || speed > 100) return;
  if (durationSec <= 0) return;
  pumpManualTimedActive = true;
  pumpManualTimedStartMs = millis();   // ← تغییر نام
  pumpManualTimedDuration = (unsigned long)durationSec * 1000UL;
  pumpManualTimedSpeed = speed;
  pumpOn(speed);
  logMsg("Pump manual-timed: " + String(speed) + "% for " + String(durationSec) + "s");
}

String getPumpStatusText() {
  String s = "Pump: ";
  if (pumpRunning) {
    s += "ON " + String(pumpCurrentSpeed) + "%";
        if (pumpManualTimedActive) {
      unsigned long rem = (pumpManualTimedDuration - (millis() - pumpManualTimedStartMs)) / 1000;   // ← تغییر نام
      s += " (manual, " + String(rem) + "s left)";
    }
  } else {
    s += "OFF";
  }
  int active = 0;
  for (int i = 0; i < MAX_PUMP_TIMERS; i++) if (pumpTimers[i].enabled) active++;
  s += "\nTimers: " + String(active) + "/10";
  return s;
}

String getPumpTimersListText() {
  String s = "=== PUMP TIMERS ===\n";
  for (int i = 0; i < MAX_PUMP_TIMERS; i++) {
    PumpTimer &t = pumpTimers[i];
    if (!t.enabled && t.source == PUMP_SRC_NONE) continue;
    s += "#" + String(i + 1) + " ";
    s += t.enabled ? "[ON] " : "[OFF] ";
    s += twoDigits(t.startHour) + ":" + twoDigits(t.startMinute) + " ";
    s += String(t.durationSec) + "s ";
    s += String(t.speed) + "% ";
    s += (t.repeatMode == PUMP_REPEAT_DAILY) ? "daily " : "once ";
    s += (t.source == PUMP_SRC_SMS) ? "SMS" : "WEB";
    if (t.isRunning) s += " *RUNNING*";
    s += "\n";
  }
  return s;
}

