void modemFlush() { while (SerialAT.available()) SerialAT.read(); }

bool modemWaitFor(const String &target, uint32_t timeout, String *response = nullptr) {
  uint32_t start = millis();
  String r;
  while (millis() - start < timeout) {
    while (SerialAT.available()) {
      char c = SerialAT.read();
      r += c;
      if (r.indexOf(target) >= 0) { if (response) *response = r; return true; }
      if (r.indexOf("ERROR") >= 0 || r.indexOf("+CME ERROR") >= 0) { if (response) *response = r; return false; }
    }
    vTaskDelay(pdMS_TO_TICKS(5));
  }
  if (response) *response = r;
  return false;
}

bool modemCommand(const String &cmd, const String &expected, uint32_t timeout, String *response = nullptr) {
  modemFlush();
  SerialAT.print(cmd);
  SerialAT.print("\r");
  return modemWaitFor(expected, timeout, response);
}

bool detectModemBaud() {
  const uint32_t bauds[] = {9600, 19200, 38400, 57600, 115200};
  for (uint8_t i = 0; i < 5; i++) {
    uint32_t b = bauds[i];
    SerialAT.end();
    SerialAT.begin(b, SERIAL_8N1, MODEM_RX, MODEM_TX);
    delay(200);
    for (int n = 0; n < 2; n++) {
      modemFlush();
      SerialAT.print("AT\r");
      uint32_t start = millis();
      String r;
      while (millis() - start < 700) {
        if (SerialAT.available()) { char c = SerialAT.read(); r += c; }
      }
      if (r.indexOf("OK") >= 0) {
        modemBaudFound = String(b);
        logMsg("SIM800 @ " + String(b));
        modemCommand("ATE0", "OK", 2000);
        return true;
      }
    }
  }
  return false;
}

void modemPowerKey() {
  pinMode(MODEM_PWRKEY, OUTPUT);
  digitalWrite(MODEM_PWRKEY, HIGH); delay(100);
  digitalWrite(MODEM_PWRKEY, LOW); delay(1200);
  digitalWrite(MODEM_PWRKEY, HIGH); delay(3000);
}

bool clearAllSMS() {
  if (!gsmReady) return false;
  for (int attempt = 0; attempt < 3; attempt++) {
    modemFlush();
    SerialAT.print("AT+CMGD=1,4\r");
    String r;
    if (modemWaitFor("OK", 5000, &r) && r.indexOf("ERROR") < 0) {
      smsCleanupOK++;
      return true;
    }
    delay(1000);
  }
  return false;
}

bool waitForNetwork(uint32_t timeout) {
  uint32_t start = millis();
  while (millis() - start < timeout) {
    String r;
    modemCommand("AT+CREG?", "OK", 2000, &r);
    if (r.indexOf(",1") >= 0 || r.indexOf(",5") >= 0) { gsmRegistered = true; return true; }
    delay(2000);
  }
  return false;
}

void updateGSMInfo() {
  if (!gsmReady) return;
  if (xSemaphoreTake(modemMutex, pdMS_TO_TICKS(5000)) != pdTRUE) return;
  String r;
  modemCommand("AT+CSQ", "OK", 3000, &r);
  int idx = r.indexOf("+CSQ:");
  if (idx >= 0) { int c = r.indexOf(",", idx); if (c > idx) gsmSignal = r.substring(idx + 5, c).toInt(); }
  modemCommand("AT+COPS?", "OK", 3000, &r);
  idx = r.indexOf("+COPS:");
  if (idx >= 0) {
    int q1 = r.indexOf("\"", idx);
    if (q1 >= 0) { int q2 = r.indexOf("\"", q1 + 1); if (q2 > q1) gsmOperator = r.substring(q1 + 1, q2); }
  }
  modemCommand("AT+CREG?", "OK", 3000, &r);
  gsmRegistered = (r.indexOf(",1") >= 0 || r.indexOf(",5") >= 0);
  xSemaphoreGive(modemMutex);
}

String getSignalQuality() {
  if (gsmSignal == 99 || gsmSignal == 0) return "No Signal";
  if (gsmSignal < 10) return "Weak";
  if (gsmSignal < 15) return "Fair";
  if (gsmSignal < 20) return "Good";
  return "Excellent";
}

bool initModem() {
  logMsg("========== SIM800 INIT ==========");
  SerialAT.begin(9600, SERIAL_8N1, MODEM_RX, MODEM_TX);
  delay(500);
  bool found = detectModemBaud();
  if (!found) { modemPowerKey(); found = detectModemBaud(); }
  if (!found) return false;
  String r;
  modemCommand("AT+CMEE=2", "OK", 2000);
  modemCommand("AT+CPIN?", "OK", 3000, &r);
  modemCommand("AT+CMGF=1", "OK", 3000);
  modemCommand("AT+CNMI=2,1,0,0,0", "OK", 3000);
  modemCommand("AT+CSQ", "OK", 3000, &r);
  modemCommand("AT+CREG?", "OK", 3000, &r);
  modemCommand("AT+COPS?", "OK", 5000, &r);
  clearAllSMS();
  gsmReady = true;
  if (waitForNetwork(30000)) logMsg("GSM registered");
  updateGSMInfo();
  return true;
}

bool parseCCLK(const String &response, uint32_t &epoch) {
  int p = response.indexOf("+CCLK:");
  if (p < 0) return false;
  String s = response.substring(p + 6);
  s.trim();
  int q1 = s.indexOf('"');
  int q2 = s.indexOf('"', q1 + 1);
  if (q1 < 0 || q2 < 0) return false;
  s = s.substring(q1 + 1, q2);
  int yy, mo, d, h, mi, sec;
  char tzSign = '+'; int tzQ = 0;
  int n = sscanf(s.c_str(), "%d/%d/%d,%d:%d:%d%c%d", &yy, &mo, &d, &h, &mi, &sec, &tzSign, &tzQ);
  if (n < 6) return false;
  int year = 2000 + yy;
  uint32_t local = makeEpoch(year, mo, d, h, mi, sec);
  if (n >= 8) {
    int offset = tzQ * 15 * 60;
    if (tzSign == '+') epoch = local - offset;
    else epoch = local + offset;
    epoch += TIMEZONE_OFFSET_SEC;
  } else epoch = local;
  if (epoch < 1700000000UL || epoch > 2200000000UL) return false;
  return true;
}

bool getTimeFromCCLK() {
  if (!gsmReady) return false;
  String r;
  modemCommand("AT+CLTS=1", "OK", 3000, &r);
  modemCommand("AT+CCLK?", "OK", 3000, &r);
  uint32_t ep;
  if (!parseCCLK(r, ep)) return false;
  savedEpoch = ep;
  epochBaseMillis = millis();
  timeReady = true;
  logMsg("TIME FROM CCLK");
  return true;
}

bool syncTimeFromSIM800() {
  if (xSemaphoreTake(modemMutex, pdMS_TO_TICKS(90000)) != pdTRUE) return false;
  bool result = getTimeFromCCLK();
  xSemaphoreGive(modemMutex);
  return result;
}

