String cleanCSVName(String n) {
  n.replace(",", "_"); n.replace("\"", "_"); n.replace("\n", "_");
  n.replace("\r", "_"); n.replace(" ", "_"); n.trim();
  return n;
}

String buildCSVHeader() {
  String hdr = "Epoch,Shamsi_Date,Shamsi_Time,Miladi_Date,Miladi_Time,";
  hdr += "Weight,Unit,Algo,ESP_Temp,AHT10_Temp,AHT10_Hum,AHT20_Temp,AHT20_Hum,";
  hdr += "Servo180,Servo360,Signal,Pump_Speed,Pump_Running";
  for (int i = 0; i < ds18b20Count; i++) {
    String name = cleanCSVName(sensorNames[i]);
    if (name.length() == 0) name = "T" + String(i + 1);
    hdr += "," + name;
  }
  hdr += ",Status";
  return hdr;
}

void createLogHeader() {
  if (!sdReady) return;
  if (SD.exists(LOG_FILE)) return;
  File f = SD.open(LOG_FILE, FILE_WRITE);
  if (f) { f.println(buildCSVHeader()); f.close(); }
}

void refreshLogHeader() {
  if (!sdReady) return;
  if (!SD.exists(LOG_FILE)) { createLogHeader(); return; }
  File f = SD.open(LOG_FILE, FILE_READ);
  if (!f) return;
  size_t fsize = f.size();
  if (fsize > 200000) { f.close(); return; }
  String content = f.readString();
  f.close();
  int nl = content.indexOf('\n');
  if (nl < 0) return;
  String oldHeader = content.substring(0, nl);
  String rest = content.substring(nl + 1);
  String newHeader = buildCSVHeader();
  if (newHeader == oldHeader) return;
  File w = SD.open(LOG_FILE, FILE_WRITE);
  if (w) { w.println(newHeader); w.print(rest); w.close(); }
}

