void setupSD() {
  SPI.begin(SD_SCK, SD_MISO, SD_MOSI, SD_CS);
  delay(100);
  if (!SD.begin(SD_CS, SPI, 1000000)) { sdReady = false; logError("SD FAIL"); return; }
  if (SD.cardType() == CARD_NONE) { sdReady = false; return; }
  sdReady = true;
  logMsg("SD OK: " + String(SD.cardSize() / (1024 * 1024)) + " MB");
}

void logAllSensors() {
  if (!sdReady || !taskStatus.logEnabled) return;
  if (xSemaphoreTake(sdMutex, pdMS_TO_TICKS(1000)) != pdTRUE) return;
  File f = SD.open(LOG_FILE, FILE_APPEND);
  if (!f) { xSemaphoreGive(sdMutex); return; }
  f.print(currentEpoch()); f.print(",");
  f.print(getShamsiDate()); f.print(",");
  f.print(getShamsiTime()); f.print(",");
  f.print(getMiladiDate()); f.print(",");
  f.print(getMiladiTime()); f.print(",");
  f.print(getWeightValue(currentWeightGrams), getWeightDecimals()); f.print(",");
  f.print(getWeightUnitStr()); f.print(",");
  f.print(algoNames[currentAlgo]); f.print(",");
  f.print(espTemp, 1); f.print(",");
  f.print(isnan(aht10Temp) ? "" : String(aht10Temp, 2)); f.print(",");
  f.print(isnan(aht10Hum) ? "" : String(aht10Hum, 1)); f.print(",");
  f.print(isnan(aht20Temp) ? "" : String(aht20Temp, 2)); f.print(",");
  f.print(isnan(aht20Hum) ? "" : String(aht20Hum, 1)); f.print(",");
  f.print(servoAngle); f.print(",");
  f.print(servo360Speed); f.print(",");
  f.print(gsmSignal); f.print(",");
  f.print(pumpCurrentSpeed); f.print(",");
  f.print(pumpRunning ? "1" : "0");
  for (int i = 0; i < ds18b20Count; i++) {
    f.print(",");
    if (!isnan(temperatures[i])) f.print(temperatures[i], 2);
  }
  f.print(",OK"); f.println(); f.close();
  totalRecords++;
  xSemaphoreGive(sdMutex);
}

