// ========== Sensors ============
// ============================================================

String addressToString(DeviceAddress addr) {
  String result = "";
  for (int i = 0; i < 8; i++) {
    if (addr[i] < 16) result += "0";
    result += String(addr[i], HEX);
  }
  return result;
}

void setupSensors() {
  sensors.begin();
  ds18b20Count = sensors.getDeviceCount();
  logMsg("DS18B20: " + String(ds18b20Count));
  byte addr[8];
  int idx = 0;
  oneWire.reset_search();
  while (oneWire.search(addr) && idx < MAX_DS18B20) {
    if (addr[0] != 0x28) continue;
    if (OneWire::crc8(addr, 7) != addr[7]) continue;
    memcpy(sensorAddresses[idx], addr, 8);
    sensorROMs[idx] = addressToString(sensorAddresses[idx]);
    if (sensorNames[idx].length() == 0) sensorNames[idx] = "sensor" + String(idx);
    idx++;
  }
  oneWire.reset_search();
  ds18b20Count = idx;
  for (int i = 0; i < MAX_DS18B20; i++) temperatures[i] = NAN;
  scale.begin(HX711_DOUT, HX711_SCK);
  delay(500);
  hx711Ready = scale.is_ready();
  if (hx711Ready) {
    scale.set_scale(hx711Factor);
    scale.set_offset(hx711Offset);
    logMsg("HX711 OK");
  }
}

void readTemperatures() {
  if (xSemaphoreTake(sensorMutex, pdMS_TO_TICKS(1500)) != pdTRUE) return;
  sensors.requestTemperatures();
  for (int i = 0; i < ds18b20Count; i++) {
    float t = sensors.getTempCByIndex(i);
    if (t != DEVICE_DISCONNECTED_C && t > -50 && t < 100)
      temperatures[i] = t + sensorCorrections[i];
  }
  espTemp = readESPTemp();
  xSemaphoreGive(sensorMutex);
}

int findSensorByName(String name) {
  name.toLowerCase();
  for (int i = 0; i < ds18b20Count; i++) {
    String sn = sensorNames[i]; sn.toLowerCase();
    if (sn == name) return i;
  }
  return -1;
}

int findSensorByROM(String rom) {
  rom.toLowerCase();
  for (int i = 0; i < ds18b20Count; i++) {
    String sr = sensorROMs[i]; sr.toLowerCase();
    if (sr == rom) return i;
  }
  return -1;
}

// ============================================================
// ========== WiFi / mDNS / OTA ============
// ============================================================

void connectWiFi() {
  WiFi.mode(WIFI_STA);
  WiFi.setAutoReconnect(true);
  WiFi.begin(wifiSSID, wifiPassword);
  uint32_t start = millis();
  while (WiFi.status() != WL_CONNECTED && millis() - start < 15000) { delay(300); }
  if (WiFi.status() == WL_CONNECTED) {
    wifiConnected = true;
    logMsg("WiFi OK IP=" + WiFi.localIP().toString());
  } else {
    wifiConnected = false;
    logWarn("WiFi FAILED");
  }
}

void setupMDNS() {
  if (!wifiConnected) {
    logWarn("mDNS skipped: no WiFi");
    return;
  }
  if (MDNS.begin(mdnsName)) {
    MDNS.addService("http", "tcp", 80);
    mdnsRunning = true;
    logMsg("mDNS: http://" + String(mdnsName) + ".local");
  } else {
    mdnsRunning = false;
    logError("mDNS failed");
  }
}

void setupOTA() {
  ArduinoOTA.setHostname(mdnsName);
  ArduinoOTA.setPassword("12345678");
  ArduinoOTA.setPort(3232);
  ArduinoOTA.onStart([]() {
    otaInProgress = true;
    logMsg("OTA START");
    led(0, 0, 80);
    taskStatus.logEnabled = false;
    taskStatus.weightEnabled = false;
    taskStatus.tempEnabled = false;
    taskStatus.smsEnabled = false;
    taskStatus.pumpEnabled = false;
    pumpOff();
  });
  ArduinoOTA.onEnd([]() {
    otaInProgress = false;
    logMsg("OTA END");
    led(0, 80, 0);
  });
  ArduinoOTA.onProgress([](unsigned int progress, unsigned int total) {
    Serial.printf("OTA: %u%%\r", (progress / (total / 100)));
  });
  ArduinoOTA.onError([](ota_error_t e) {
    otaInProgress = false;
    logError("OTA ERROR: " + String(e));
    taskStatus.logEnabled = true;
    taskStatus.weightEnabled = true;
    taskStatus.tempEnabled = true;
    taskStatus.smsEnabled = true;
    taskStatus.pumpEnabled = true;
  });
  ArduinoOTA.begin();
  logMsg("OTA ready");
}

