// ============================================================
// ========== Send SMS ==========
// ============================================================

void sendSMS(String number, String message) {
  led(50, 50, 0);
  if (xSemaphoreTake(modemMutex, pdMS_TO_TICKS(15000)) != pdTRUE) return;
  modemCommand("AT+CMGF=1", "OK", 3000);
  modemFlush();
  SerialAT.print("AT+CMGS=\"" + number + "\"\r");
  String r;
  if (!modemWaitFor(">", 5000, &r)) { xSemaphoreGive(modemMutex); return; }
  SerialAT.print(message);
  SerialAT.write(26);
  bool ok = modemWaitFor("OK", 15000, &r);
  xSemaphoreGive(modemMutex);
  if (ok) { led(0, 50, 0); delay(200); led(0, 0, 0); }
}

// ============================================================
// ========== Check Incoming SMS ==========
// ============================================================

void checkIncomingSMS() {
  if (!gsmReady) return;
  if (xSemaphoreTake(modemMutex, pdMS_TO_TICKS(15000)) != pdTRUE) return;

  modemFlush();
  SerialAT.print("AT+CMGF=1\r");
  String cmgfR;
  modemWaitFor("OK", 2000, &cmgfR);

  modemFlush();
  SerialAT.print("AT+CMGL=\"REC UNREAD\"\r");
  String response;
  bool got = modemWaitFor("OK", 5000, &response);

  if (!got || response.indexOf("ERROR") >= 0) {
    smsReadError++;
    SerialAT.print("AT+CMGD=1,4\r");
    String clrR;
    modemWaitFor("OK", 5000, &clrR);
    xSemaphoreGive(modemMutex);
    return;
  }

  smsReadOK++;

  if (response.indexOf("+CMGL") < 0) {
    SerialAT.print("AT+CMGD=1,4\r");
    String clrR; modemWaitFor("OK", 3000, &clrR);
    xSemaphoreGive(modemMutex);
    return;
  }

  int numStart = response.indexOf("\"+");
  if (numStart < 0) numStart = response.indexOf("\"0098");
  if (numStart < 0) numStart = response.indexOf("\"98");
  if (numStart < 0) {
    SerialAT.print("AT+CMGD=1,4\r");
    String clrR; modemWaitFor("OK", 3000, &clrR);
    xSemaphoreGive(modemMutex);
    return;
  }

  int numEnd = response.indexOf("\"", numStart + 1);
  if (numEnd < 0) { xSemaphoreGive(modemMutex); return; }
  String number = response.substring(numStart + 1, numEnd);

  int msgStart = response.indexOf("\n", numEnd);
  if (msgStart < 0) { xSemaphoreGive(modemMutex); return; }
  int msgEnd = response.indexOf("\n", msgStart + 1);
  if (msgEnd < 0) msgEnd = response.length();
  String message = response.substring(msgStart + 1, msgEnd);
  message.trim();

  SerialAT.print("AT+CMGD=1,4\r");
  String clrR;
  if (modemWaitFor("OK", 5000, &clrR)) smsDeletedOK++;

  xSemaphoreGive(modemMutex);

  String cleanNum = number;
  cleanNum.replace("+98", ""); cleanNum.replace("0098", ""); cleanNum.replace("+", "");
  String cleanAuth = authorizedNumber;
  cleanAuth.replace("+98", ""); cleanAuth.replace("0098", ""); cleanAuth.replace("+", "");

  if (cleanNum != cleanAuth && number.indexOf("9140714453") < 0) {
    sendSMS(number, "Not authorized");
    return;
  }

  processSMS(number, message);
  smsProcessedOK++;
}

// ============================================================
// ========== processSMS ============
// ============================================================

void processSMS(String number, String message) {
  String lower = message;
  lower.toLowerCase();
  String original = message;

  // ===== Help =====
  if (lower.indexOf("helppump") >= 0) { sendSMS(number, getHelpPump()); return; }
  if (lower.indexOf("helpservo360") >= 0) { sendSMS(number, getHelpServo360()); return; }
  if (lower.indexOf("helpservo") >= 0) { sendSMS(number, getHelpServo()); return; }
  if (lower.indexOf("helpi2c") >= 0) { sendSMS(number, getHelpI2C()); return; }
  if (lower.indexOf("helpsms") >= 0) { sendSMS(number, getHelpSMS()); return; }
  if (lower.indexOf("helptemp") >= 0) { sendSMS(number, getHelpTemp()); return; }
  if (lower.indexOf("helpweight") >= 0) { sendSMS(number, getHelpWeight()); return; }
  if (lower.indexOf("helptask") >= 0) { sendSMS(number, getHelpTask()); return; }
  if (lower.indexOf("helpwifi") >= 0) { sendSMS(number, getHelpWiFi()); return; }
  if (lower.indexOf("helptime") >= 0) { sendSMS(number, getHelpTime()); return; }
  if (lower.indexOf("helpprefer") >= 0) { sendSMS(number, getHelpPrefer()); return; }
  if (lower.indexOf("helpsystem") >= 0) { sendSMS(number, getHelpSystem()); return; }
  if (lower.indexOf("helpsyslog") >= 0) { sendSMS(number, getHelpSyslog()); return; }
  if (lower.indexOf("help") >= 0) { sendSMS(number, getHelpMain()); return; }

  // ============================================================
  // ===== PUMP Commands =====
  // ============================================================

  // pompset HH MM Ds Sr daily/once [tN]
  if (lower.indexOf("pompset") >= 0) {
    String rest = original;
    rest.replace("pompset", "");
    rest.replace("Pompset", "");
    rest.replace("POMPSET", "");
    rest.trim();
    rest.replace("  ", " ");

    int nums[3] = {0, 0, 0};
    int nCount = 0;
    int durSec = -1, spdPct = -1;
    String repeatStr = "";
    int targetSlot = -1;

    // جدا کردن توکن‌ها
    String tokens[10];
    int tokenCount = 0;
    int start = 0;
    for (int i = 0; i <= (int)rest.length() && tokenCount < 10; i++) {
      if (i == (int)rest.length() || rest.charAt(i) == ' ') {
        if (i > start) {
          tokens[tokenCount++] = rest.substring(start, i);
        }
        start = i + 1;
      }
    }

    bool parseErr = false;
    for (int i = 0; i < tokenCount; i++) {
      String tk = tokens[i];
      tk.toLowerCase();
      if (tk.endsWith("s") && tk.length() > 1) {
        durSec = tk.substring(0, tk.length() - 1).toInt();
      } else if (tk.endsWith("r") && tk.length() > 1) {
        spdPct = tk.substring(0, tk.length() - 1).toInt();
      } else if (tk == "daily" || tk == "once") {
        repeatStr = tk;
      } else if (tk.startsWith("t") && tk.length() >= 2) {
        int slotNum = tk.substring(1).toInt();
        if (slotNum >= 1 && slotNum <= 10) targetSlot = slotNum - 1;
      } else if (nCount < 2) {
        nums[nCount++] = tk.toInt();
      }
    }

    if (nCount < 2 || durSec <= 0 || spdPct <= 0 || spdPct > 100 || repeatStr == "") {
      sendSMS(number, "Format: pompset HH MM Xs Yr daily/once [tN]");
      return;
    }

    int h = nums[0], mi = nums[1];
    if (h < 0 || h > 23 || mi < 0 || mi > 59) { sendSMS(number, "Invalid time"); return; }

    PumpRepeat rep = (repeatStr == "daily") ? PUMP_REPEAT_DAILY : PUMP_REPEAT_ONCE;

    // تعیین اسلات
    int slot = targetSlot;
    if (slot < 0) {
      // اولین اسلات خالی
      for (int i = 0; i < MAX_PUMP_TIMERS; i++) {
        if (!pumpTimers[i].enabled && pumpTimers[i].source == PUMP_SRC_NONE) { slot = i; break; }
      }
      if (slot < 0) {
        // همه پر
        sendSMS(number, "tumer full");
        return;
      }
    }

    pumpTimers[slot].enabled = true;
    pumpTimers[slot].startHour = h;
    pumpTimers[slot].startMinute = mi;
    pumpTimers[slot].durationSec = durSec;
    pumpTimers[slot].speed = spdPct;
    pumpTimers[slot].repeatMode = rep;
    pumpTimers[slot].source = PUMP_SRC_SMS;
    pumpTimers[slot].executedToday = false;
    pumpTimers[slot].lastExecDayKey = -1;
    savePumpTimers();

    String info = "Timer #" + String(slot + 1) + " set\n";
    info += "Time: " + twoDigits(h) + ":" + twoDigits(mi) + "\n";
    info += "Duration: " + String(durSec) + "s\n";
    info += "Speed: " + String(spdPct) + "%\n";
    info += "Repeat: " + repeatStr;
    sendSMS(number, info);
    return;
  }

  // pump del tN
  if (lower.indexOf("pump del t") >= 0) {
    int idx = lower.indexOf("pump del t") + 10;
    int slotNum = lower.substring(idx).toInt();
    if (slotNum >= 1 && slotNum <= 10) {
      int s = slotNum - 1;
      pumpTimers[s].enabled = false;
      pumpTimers[s].source = PUMP_SRC_NONE;
      pumpTimers[s].isRunning = false;
      pumpTimers[s].durationSec = 0;
      pumpTimers[s].speed = 0;
      savePumpTimers();
      sendSMS(number, "Timer #" + String(slotNum) + " deleted");
    } else sendSMS(number, "Range: t1-t10");
    return;
  }

  // pump clear
  if (lower.indexOf("pump clear") >= 0) {
    for (int i = 0; i < MAX_PUMP_TIMERS; i++) {
      pumpTimers[i].enabled = false;
      pumpTimers[i].source = PUMP_SRC_NONE;
      pumpTimers[i].isRunning = false;
      pumpTimers[i].durationSec = 0;
      pumpTimers[i].speed = 0;
    }
    pumpOff();
    savePumpTimers();
    sendSMS(number, "All timers cleared");
    return;
  }

  // pump save on/off
  if (lower.indexOf("pump save on") >= 0) {
    pumpTimersSaveEnabled = true;
    savePumpTimers();
    sendSMS(number, "Timers save: ON");
    return;
  }
  if (lower.indexOf("pump save off") >= 0) {
    pumpTimersSaveEnabled = false;
    savePumpTimers();
    sendSMS(number, "Timers save: OFF");
    return;
  }

  // pump list
  if (lower.indexOf("pump list") >= 0) {
    sendSMS(number, getPumpTimersListText());
    return;
  }

  // pump status
  if (lower.indexOf("pump status") >= 0) {
    String s = getPumpStatusText() + "\n\n" + getPumpTimersListText();
    sendSMS(number, s);
    return;
  }

  // pump run X Y  (manual timed)
  if (lower.indexOf("pump run ") >= 0) {
    String rest = lower.substring(lower.indexOf("pump run ") + 9);
    rest.trim();
    int sp = rest.indexOf(' ');
    if (sp < 0) { sendSMS(number, "Format: pump run SPEED DURATION"); return; }
    int speed = rest.substring(0, sp).toInt();
    int durSec = rest.substring(sp + 1).toInt();
    if (speed <= 0 || speed > 100) { sendSMS(number, "Speed 1-100"); return; }
    if (durSec <= 0 || durSec > 3600) { sendSMS(number, "Duration 1-3600s"); return; }
    pumpManualTimedStart(speed, durSec);
    sendSMS(number, "Pump " + String(speed) + "% for " + String(durSec) + "s");
    return;
  }

  // pump on X
  if (lower.indexOf("pump on ") >= 0) {
    int speed = lower.substring(lower.indexOf("pump on ") + 8).toInt();
    if (speed <= 0 || speed > 100) { sendSMS(number, "Speed 1-100"); return; }
    pumpManualMode = true;
    pumpManualTimedActive = false;
    pumpOn(speed);
    sendSMS(number, "Pump ON @" + String(speed) + "%");
    return;
  }

  // pump off
  if (lower.indexOf("pump off") >= 0) {
    pumpOff();
    sendSMS(number, "Pump OFF");
    return;
  }

  // ===== mDNS =====
  if (lower.indexOf("mdns status") >= 0) {
    String info = "mDNS:\nName: " + String(mdnsName) + "\n";
    info += "URL: http://" + String(mdnsName) + ".local\n";
    info += "Running: " + String(mdnsRunning ? "YES" : "NO");
    sendSMS(number, info);
    return;
  }
  if (lower.indexOf("mdns ") >= 0) {
    String newName = message.substring(message.indexOf("mdns ") + 5);
    newName.trim();
    newName.toLowerCase();
    newName.replace(" ", "");
    if (newName.length() > 0 && newName.length() < 30) {
      newName.toCharArray(mdnsName, sizeof(mdnsName));
      saveSettings();
      sendSMS(number, "mDNS: " + newName + "\nReboot needed");
    } else sendSMS(number, "Invalid name");
    return;
  }
  if (lower.indexOf("mdns") >= 0) {
    sendSMS(number, "http://" + String(mdnsName) + ".local");
    return;
  }

  // ===== SIM800 On/Off =====
  if (lower.indexOf("gsm off") >= 0) {
    sendSMS(number, "SIM800: OFF");
    delay(2000);
    if (xSemaphoreTake(modemMutex, pdMS_TO_TICKS(5000)) == pdTRUE) {
      modemCommand("AT+CPOWD=1", "NORMAL POWER DOWN", 5000);
      gsmReady = false;
      gsmRegistered = false;
      xSemaphoreGive(modemMutex);
    }
    return;
  }
  if (lower.indexOf("gsm on") >= 0) {
    sendSMS(number, "SIM800: ON");
    delay(2000);
    if (xSemaphoreTake(modemMutex, pdMS_TO_TICKS(20000)) == pdTRUE) {
      modemPowerKey();
      delay(5000);
      if (detectModemBaud()) {
        modemCommand("AT+CMGF=1", "OK", 3000);
        modemCommand("AT+CNMI=2,1,0,0,0", "OK", 3000);
        gsmReady = true;
        waitForNetwork(30000);
        updateGSMInfo();
        xSemaphoreGive(modemMutex);
        sendSMS(number, "SIM800: Ready");
        return;
