  }

  // ===== Servo 360 =====
  if (lower.indexOf("servo360 status") >= 0) {
    String info = "Servo360:\nSpeed: " + String(servo360Speed) + "%\n";
    info += "Target: " + String(servo360Target) + "%\n";
    info += "Ramping: " + String(servo360Ramping ? "YES" : "NO") + "\n";
    info += "Turning: " + String(servo360Turning ? "YES" : "NO") + "\n";
    info += "Enabled: " + String(servo360Enabled ? "YES" : "NO") + "\n";
    info += "Ramp: " + getRampName() + "\n";
