  }
  if (lower.indexOf("servo360 stop") >= 0) { stopServo360Soft(); sendSMS(number, "Servo360: soft stop"); return; }
  if (lower.indexOf("servo360 estop") >= 0) { stopServo360Immediate(); sendSMS(number, "Servo360: E-STOP"); return; }
  if (lower.indexOf("servo360 off") >= 0) {
    servo360Enabled = false;
    servo360Speed = 0; servo360Target = 0;
