  }
  if (lower.indexOf("servo360 on") >= 0) { servo360Enabled = true; saveSettings(); sendSMS(number, "Servo360: ON"); return; }
  if (lower.indexOf("servo360 ") >= 0) {
    String rest = lower.substring(lower.indexOf("servo360 ") + 9);
    rest.trim();
    int sp = rest.toInt();
    if (sp >= -100 && sp <= 100) { setServo360Speed(sp); sendSMS(number, "Servo360: " + String(sp) + "%"); }
    else sendSMS(number, "Speed -100..+100");
    return;
  }

  // ===== Turn =====
  if (lower.indexOf("turncal show") >= 0) { sendSMS(number, "TurnCal: " + String(turnCalibration, 3)); return; }
  if (lower.indexOf("turncal reset") >= 0) { turnCalibration = 1.0; saveSettings(); sendSMS(number, "TurnCal reset"); return; }
  if (lower.indexOf("turncal ") >= 0) {
    float v = lower.substring(lower.indexOf("turncal ") + 8).toFloat();
    if (v > 0.1 && v < 100) { turnCalibration = v; saveSettings(); sendSMS(number, "TurnCal: " + String(v, 2)); }
    else sendSMS(number, "Range: 0.1-100");
    return;
  }
  if (lower.indexOf("turn stop") >= 0) { stopServo360Soft(); sendSMS(number, "Turn: stopped"); return; }
  if (lower.indexOf("turn ") >= 0) {
    String rest = lower.substring(lower.indexOf("turn ") + 5);
    rest.trim();
    int sp = rest.indexOf(' ');
    if (sp < 0) { sendSMS(number, "Format: turn N SPEED"); return; }
    float revs = rest.substring(0, sp).toFloat();
    int speed = rest.substring(sp + 1).toInt();
    if (revs == 0) { sendSMS(number, "Revs != 0"); return; }
    if (abs(speed) < 10 || abs(speed) > 100) { sendSMS(number, "Speed 10-100"); return; }
    startServo360Turns(revs, speed);
    float oneRevS = SERVO360_FULL_REV_MS / 1000.0 / abs(speed) * 100.0 / turnCalibration;
    float totalS = oneRevS * abs(revs);
    sendSMS(number, "Turn: " + String(revs) + " rev @ " + String(abs(speed)) + "%\nTime: ~" + String(totalS, 1) + "s");
    return;
  }

  // ===== Ramp =====
  if (lower.indexOf("ramp status") >= 0) {
    String info = "Ramp: " + getRampName() + "\n";
    info += "Step: " + String(getRampStep()) + "\n";
    info += "Delay: " + String(getRampDelay()) + "ms";
    sendSMS(number, info);
    return;
