  if (lower.indexOf("ramp instant") >= 0) { currentRamp = RAMP_INSTANT; saveSettings(); sendSMS(number, "Ramp: INSTANT"); return; }
  if (lower.indexOf("ramp fast") >= 0) { currentRamp = RAMP_FAST; saveSettings(); sendSMS(number, "Ramp: FAST"); return; }
  if (lower.indexOf("ramp normal") >= 0) { currentRamp = RAMP_NORMAL; saveSettings(); sendSMS(number, "Ramp: NORMAL"); return; }
  if (lower.indexOf("ramp smooth") >= 0) { currentRamp = RAMP_SMOOTH; saveSettings(); sendSMS(number, "Ramp: SMOOTH"); return; }
  if (lower.indexOf("ramp very") >= 0) { currentRamp = RAMP_VERY_SMOOTH; saveSettings(); sendSMS(number, "Ramp: VERY SMOOTH"); return; }
  if (lower.indexOf("ramp custom ") >= 0) {
    String rest = lower.substring(lower.indexOf("ramp custom ") + 12);
    rest.trim();
    int sp = rest.indexOf(' ');
    if (sp < 0) { sendSMS(number, "Format: ramp custom STEP DELAY"); return; }
    int step = rest.substring(0, sp).toInt();
    int delayMs = rest.substring(sp + 1).toInt();
    if (step >= 1 && step <= 100 && delayMs >= 0 && delayMs <= 1000) {
      customRampStep = step; customRampDelay = delayMs;
      currentRamp = RAMP_CUSTOM;
      saveSettings();
      sendSMS(number, "Custom: " + String(step) + "/" + String(delayMs) + "ms");
