  if (lower.indexOf("servo on") >= 0) { servoEnabled = true; saveSettings(); sendSMS(number, "Servo180 ON"); return; }
  if (lower.indexOf("servo off") >= 0) { servoEnabled = false; saveSettings(); sendSMS(number, "Servo180 OFF"); return; }
  if (lower.indexOf("servo min ") >= 0) {
    int v = lower.substring(lower.indexOf("servo min ") + 10).toInt();
