  if (lower.indexOf("servo center") >= 0) { servoPreset("center"); sendSMS(number, "Center"); return; }
  if (lower.indexOf("servo sweep") >= 0) { sendSMS(number, "Sweep..."); servoPreset("sweep"); sendSMS(number, "Done"); return; }
  if (lower.indexOf("servo toggle") >= 0) { servoPreset("toggle"); sendSMS(number, "Toggle"); return; }
  if (lower.indexOf("servo wave") >= 0) { sendSMS(number, "Wave..."); servoPreset("wave"); sendSMS(number, "Done"); return; }
  if (lower.indexOf("servo nod") >= 0) { sendSMS(number, "Nod..."); servoPreset("nod"); sendSMS(number, "Done"); return; }
  if (lower.indexOf("servo shake") >= 0) { sendSMS(number, "Shake..."); servoPreset("shake"); sendSMS(number, "Done"); return; }
  if (lower.indexOf("servo scan") >= 0) { sendSMS(number, "Scan..."); servoPreset("scan"); sendSMS(number, "Done"); return; }
  if (lower.indexOf("servo open") >= 0) { servoPreset("open"); sendSMS(number, "Open"); return; }
  if (lower.indexOf("servo close") >= 0) { servoPreset("close"); sendSMS(number, "Close"); return; }
    if (lower.indexOf("servo ") >= 0) {
    String a = lower.substring(6);
    a.trim();
    int angle = a.toInt();
    if (angle >= 0 && angle <= 180) {
      if (setServoAngle(angle)) sendSMS(number, "Servo180: " + String(angle) + "°");
      else sendSMS(number, "Failed");
    } else sendSMS(number, "Angle 0-180");
    return;
  }

  // ===== I2C =====
  if (lower.indexOf("i2c scan") >= 0) {
    String info = "I2C Scan:\n\nBus 0:\n";
    for (byte addr = 1; addr < 127; addr++) {
      Wire.beginTransmission(addr);
      if (Wire.endTransmission() == 0) info += "0x" + String(addr, HEX) + "\n";
    }
    info += "Bus 1:\n";
    for (byte addr = 1; addr < 127; addr++) {
      Wire1.beginTransmission(addr);
      if (Wire1.endTransmission() == 0) info += "0x" + String(addr, HEX) + "\n";
    }
    sendSMS(number, info);
    return;
  }
  if (lower.indexOf("i2c rescan") >= 0) {
    aht10Ready = false; aht20Ready = false; oledReady = false;
    delay(200);
    checkI2CDevices();
    String info = "AHT10:" + String(aht10Ready ? "OK" : "NO");
    info += " AHT20:" + String(aht20Ready ? "OK" : "NO");
    info += " OLED:" + String(oledReady ? "OK" : "NO");
    sendSMS(number, info);
    return;
  }
  if (lower.indexOf("i2c status") >= 0) {
    String info = "AHT10:" + String(aht10Ready ? "OK" : "NO");
    info += "\nAHT20:" + String(aht20Ready ? "OK" : "NO");
    info += "\nOLED:" + String(oledReady ? "OK" : "NO");
    sendSMS(number, info);
    return;
  }
  if (lower.indexOf("sethum aht10 ") >= 0) {
    float v = original.substring(original.indexOf("sethum aht10 ") + 13).toFloat();
    if (v >= -30 && v <= 30) { aht10HumOffset = v; saveSettings(); sendSMS(number, "AHT10 offset: " + String(v, 1)); }
    return;
  }
  if (lower.indexOf("sethum aht20 ") >= 0) {
    float v = original.substring(original.indexOf("sethum aht20 ") + 13).toFloat();
