    info += "AHT20: " + String(aht20Hum, 1) + "% (off " + String(aht20HumOffset, 1) + ")";
    sendSMS(number, info);
    return;
  }
  if (lower.indexOf("aht10") >= 0) {
    if (!aht10Ready) { sendSMS(number, "AHT10 not ready"); return; }
    readAHT();
    sendSMS(number, "AHT10:\nT: " + String(aht10Temp, 2) + " C\nH: " + String(aht10Hum, 1) + " %");
    return;
  }
  if (lower.indexOf("aht20") >= 0) {
    if (!aht20Ready) { sendSMS(number, "AHT20 not ready"); return; }
