    sendSMS(number, "AHT20:\nT: " + String(aht20Temp, 2) + " C\nH: " + String(aht20Hum, 1) + " %");
    return;
  }
  if (lower.indexOf("aht") >= 0) {
    readAHT();
    String info = "AHT:\nAHT10: ";
    if (aht10Ready) info += String(aht10Temp, 1) + "C " + String(aht10Hum, 0) + "%";
    else info += "N/A";
    info += "\nAHT20: ";
    if (aht20Ready) info += String(aht20Temp, 1) + "C " + String(aht20Hum, 0) + "%";
    else info += "N/A";
    sendSMS(number, info);
    return;
  }
  if (lower.indexOf("oled on") >= 0) { oledEnabled = true; saveSettings(); sendSMS(number, "OLED ON"); return; }
  if (lower.indexOf("oled off") >= 0) {
    oledEnabled = false;
    if (oledReady) { oled.clearBuffer(); oled.sendBuffer(); }
    saveSettings();
    sendSMS(number, "OLED OFF");
    return;
  }
  if (lower.indexOf("oled page ") >= 0) {
    int p = lower.substring(lower.indexOf("oled page ") + 10).toInt();
    if (p >= 0 && p <= 6) { oledPage = p; updateOLED(); sendSMS(number, "Page: " + String(p)); }
    else sendSMS(number, "Page 0-6");
    return;
  }

  // ===== SMS Debug =====
  if (lower.indexOf("smsinfo") >= 0) {
    if (xSemaphoreTake(modemMutex, pdMS_TO_TICKS(5000)) == pdTRUE) {
      String r;
      modemCommand("AT+CPMS?", "OK", 3000, &r);
      xSemaphoreGive(modemMutex);
      sendSMS(number, "SMS:\n" + r);
    }
    return;
  }
  if (lower.indexOf("smsclear") >= 0) {
    if (xSemaphoreTake(modemMutex, pdMS_TO_TICKS(5000)) == pdTRUE) {
      bool ok = clearAllSMS();
      xSemaphoreGive(modemMutex);
      sendSMS(number, ok ? "Cleared" : "Failed");
    }
    return;
  }
  if (lower.indexOf("smstest") >= 0) { sendSMS(number, "Test OK\n" + getShamsiTime()); return; }
  if (lower.indexOf("smstats") >= 0) {
    String s = "SMS:\nOK:" + String(smsReadOK) + "\nErr:" + String(smsReadError);
    s += "\nProc:" + String(smsProcessedOK) + "\nDel:" + String(smsDeletedOK);
    sendSMS(number, s);
    return;
  }
  if (lower.indexOf("modemreset") >= 0) {
    sendSMS(number, "Resetting...");
    delay(2000);
    if (xSemaphoreTake(modemMutex, pdMS_TO_TICKS(15000)) == pdTRUE) {
      modemPowerKey(); delay(5000);
      if (detectModemBaud()) {
        modemCommand("AT+CMGF=1", "OK", 3000);
        modemCommand("AT+CNMI=2,1,0,0,0", "OK", 3000);
        xSemaphoreGive(modemMutex);
        sendSMS(number, "Reset OK");
        return;
      }
      xSemaphoreGive(modemMutex);
    }
    return;
  }

  // ===== Time =====
  if (lower.indexOf("timesync") >= 0) {
    sendSMS(number, "Syncing...");
    bool ok = false;
    if (wifiConnected) ok = syncTimeFromNTP();
    if (!ok) ok = syncTimeFromSIM800();
    sendSMS(number, ok ? "OK\n" + getFormattedTimeResponse() : "FAILED");
    return;
  }
  if (lower.indexOf("settime") >= 0) {
    bool shamsi = (lower.indexOf("shamsi") >= 0);
    String clean = original;
    clean.replace("settime", ""); clean.replace("shamsi", "");
    clean.replace("SetTime", ""); clean.replace("SETTIME", "");
    clean.replace("Shamsi", ""); clean.trim();
    clean.replace("/", " "); clean.replace(":", " "); clean.replace("-", " ");

    int nums[8], cnt = 0;
    String cur = "";
    for (int i = 0; i < (int)clean.length() && cnt < 6; i++) {
      char c = clean.charAt(i);
      if (c >= '0' && c <= '9') cur += c;
      else if (cur.length() > 0) { nums[cnt++] = cur.toInt(); cur = ""; }
    }
    if (cur.length() > 0 && cnt < 6) nums[cnt++] = cur.toInt();

    if (cnt < 6) {
      sendSMS(number, "Format:\nsettime Y M D H M S\nsettime shamsi JY JM JD H M S");
      return;
    }

    int y = nums[0], mo = nums[1], d = nums[2];
    int h = nums[3], mi = nums[4], s = nums[5];

    if (shamsi) {
      int gy, gm, gd;
      jalaliToGregorian(y, mo, d, gy, gm, gd);
      y = gy; mo = gm; d = gd;
    }

    uint32_t epoch = makeEpoch(y, mo, d, h, mi, s);
    if (epoch == 0) { sendSMS(number, "Invalid date"); return; }

    epoch -= TIMEZONE_OFFSET_SEC;
    savedEpoch = epoch;
    epochBaseMillis = millis();
    timeReady = true;
    sendSMS(number, "Set!\n" + getFormattedTimeResponse());
    return;
  }
  if (lower.indexOf("time") >= 0 && message.length() < 10) {
    sendSMS(number, getFormattedTimeResponse());
    return;
  }

  // ===== Temp =====
  if (lower.indexOf("temp correct list") >= 0) {
    String info = "Corrections:\n";
    for (int i = 0; i < ds18b20Count; i++) info += sensorNames[i] + ": " + String(sensorCorrections[i], 2) + "\n";
    sendSMS(number, info);
    return;
  }
  if (lower.indexOf("temp correct reset") >= 0) {
    for (int i = 0; i < ds18b20Count; i++) sensorCorrections[i] = 0.0;
