    sensorNames[si] = n;
    saveSensorNames();
    refreshLogHeader();
    sendSMS(number, "OK: " + n);
    return;
  }
  if (lower.indexOf("temp rename ") >= 0) {
    String rest = original.substring(original.indexOf("temp rename ") + 12);
