    if (sp < 0) { sendSMS(number, "temp rename OLD NEW"); return; }
    String o = rest.substring(0, sp);
    String n = rest.substring(sp + 1);
    o.trim(); n.trim();
    int si = findSensorByName(o);
    if (si < 0) { sendSMS(number, "Not found"); return; }
    sensorNames[si] = n;
    saveSensorNames();
    refreshLogHeader();
    sendSMS(number, "Renamed: " + n);
