    sendSMS(number, "Found " + String(nc) + ". Total " + String(ds18b20Count));
    return;
  }
  if (lower.indexOf("temp reset") >= 0) {
    for (int i = 0; i < ds18b20Count; i++) { sensorNames[i] = "sensor" + String(i); sensorCorrections[i] = 0; }
