    info += "RAW: " + String(algoRaw(weightBuffer[(weightBufferIdx-1+WBUF_SIZE)%WBUF_SIZE]), 1) + "\n";
    info += "AVG10: " + String(algoAvg10(), 1) + "\n";
    info += "AVG20: " + String(algoAvg20(), 1) + "\n";
    info += "TRIMMED: " + String(algoTrimmed(), 1) + "\n";
    info += "Current: " + String(currentWeightGrams, 1);
    sendSMS(number, info);
    return;
  }
  if (lower.indexOf("weight algo status") >= 0) {
    String info = "Algo: " + String(algoNames[currentAlgo]) + "\n";
    info += "Buffer: " + String(weightBufferCount) + "/" + String(WBUF_SIZE) + "\n";
    info += "Alpha: " + String(emaAlpha, 2);
    sendSMS(number, info);
    return;
  }
  if (lower.indexOf("weight algo alpha ") >= 0) {
    float v = lower.substring(lower.indexOf("alpha ") + 6).toFloat();
    if (v >= 0.05 && v <= 1.0) { emaAlpha = v; saveSettings(); sendSMS(number, "Alpha: " + String(v, 2)); }
    else sendSMS(number, "Alpha 0.05-1.0");
    return;
  }
  if (lower.indexOf("weight algo ") >= 0) {
    String a = lower.substring(lower.indexOf("weight algo ") + 12);
    a.trim();
    int idx = -1;
    for (int i = 0; i < 10; i++) {
      String n = algoNames[i]; n.toLowerCase();
      if (n == a) { idx = i; break; }
    }
    if (idx >= 0) {
      currentAlgo = (WeightAlgo)idx;
      resetWeightFilter();
      saveSettings();
      sendSMS(number, "Algo: " + String(algoNames[idx]));
    } else sendSMS(number, "Unknown. Use: weight algo list");
    return;
  }
  if (lower.indexOf("weight") >= 0 && message.length() < 10) {
    sendSMS(number, "Weight: " + formatWeight(currentWeightGrams));
    return;
  }

  // ===== Task =====
  if (lower.indexOf("task status") >= 0) {
    String s = "Tasks:\nwifi:" + String(taskStatus.wifiEnabled ? "ON" : "OFF");
    s += "\nntp:" + String(taskStatus.ntpEnabled ? "ON" : "OFF");
    s += "\nsms:" + String(taskStatus.smsEnabled ? "ON" : "OFF");
    s += "\ntemp:" + String(taskStatus.tempEnabled ? "ON" : "OFF");
    s += "\nweight:" + String(taskStatus.weightEnabled ? "ON" : "OFF");
    s += "\nlog:" + String(taskStatus.logEnabled ? "ON" : "OFF");
    s += "\npump:" + String(taskStatus.pumpEnabled ? "ON" : "OFF");
    sendSMS(number, s);
    return;
  }
  if (lower.indexOf("task all on") >= 0) {
    taskStatus.wifiEnabled = taskStatus.ntpEnabled = taskStatus.simTimeEnabled = true;
    taskStatus.smsEnabled = taskStatus.ledEnabled = taskStatus.monitorEnabled = true;
    taskStatus.tempEnabled = taskStatus.weightEnabled = taskStatus.logEnabled = true;
    taskStatus.pumpEnabled = true;
    sendSMS(number, "All ON");
    return;
  }
  if (lower.indexOf("task all off") >= 0) {
    taskStatus.wifiEnabled = taskStatus.ntpEnabled = taskStatus.simTimeEnabled = false;
    taskStatus.smsEnabled = taskStatus.ledEnabled = taskStatus.monitorEnabled = false;
    taskStatus.tempEnabled = taskStatus.weightEnabled = taskStatus.logEnabled = false;
    taskStatus.pumpEnabled = false;
    pumpOff();
    sendSMS(number, "All OFF");
    return;
  }

  // ===== WiFi =====
  if (lower.indexOf("wifi show") >= 0) {
    String info = "WiFi: " + String(wifiSSID) + "\n";
    info += "Status: " + String(wifiConnected ? "OK" : "NO") + "\n";
    info += "IP: " + WiFi.localIP().toString() + "\n";
    info += "mDNS: http://" + String(mdnsName) + ".local";
    sendSMS(number, info);
    return;
  }
  if (lower.indexOf("wifi reconnect") >= 0) {
    WiFi.disconnect(); delay(500);
    WiFi.begin(wifiSSID, wifiPassword);
    sendSMS(number, "Reconnecting");
    return;
  }

  // ===== Prefer / Reboot / Signal =====
  if (lower.indexOf("prefer") >= 0) { saveAllPreferences(); sendSMS(number, "ALL SAVED"); return; }
  if (lower.indexOf("reboot") >= 0) {
    sendSMS(number, "Rebooting...");
    delay(2000);
    ESP.restart();
    return;
  }
  if (lower.indexOf("signal") >= 0) {
    updateGSMInfo();
    String info = "Signal: " + String(gsmSignal) + "/31\n" + getSignalQuality();
    info += "\nOp: " + gsmOperator;
    sendSMS(number, info);
    return;
  }
  if (lower.indexOf("esp temp") >= 0) {
    sendSMS(number, "ESP: " + String(espTemp, 1) + " C");
    return;
  }
  if (message.indexOf("321") >= 0) {
    sendSMS(number, "321 OK\n" + getFormattedTimeResponse());
    return;
  }

  sendSMS(number, "Unknown. Send help");
}

// ============================================================
// ========== Tasks ============
// ============================================================

void TaskWebCode(void *pvParameters) {
  while (true) { server.handleClient(); ArduinoOTA.handle(); delay(2); }
}

void TaskLEDCode(void *pvParameters) {
  bool state = false;
  while (true) {
    if (taskStatus.ledEnabled && !otaInProgress) {
      state = !state;
      if (state) {
        if (timeReady && wifiConnected) led(0, 30, 30);
        else if (timeReady) led(30, 30, 0);
        else led(30, 0, 0);
      } else led(0, 0, 0);
    }
    delay(1000);
  }
}

void TaskSensorsCode(void *pvParameters) {
  unsigned long lastTemp = 0;
  unsigned long lastWeight = 0;
  while (true) {
    unsigned long now = millis();
    if (now - lastTemp >= TEMP_READ_INTERVAL || forceRunTemp) {
      lastTemp = now;
      forceRunTemp = false;
      readTemperatures();
    }
    if (now - lastWeight >= WEIGHT_SAMPLE_INTERVAL || forceRunWeight) {
      lastWeight = now;
      forceRunWeight = false;
      sampleWeightFast();
    }
    delay(10);
  }
}

void TaskI2CCode(void *pvParameters) {
  unsigned long lastAHT = 0;
  unsigned long lastOLED = 0;
  unsigned long lastCheck = 0;
  while (true) {
    unsigned long now = millis();
    if (now - lastCheck >= I2C_CHECK_INTERVAL) { lastCheck = now; checkI2CDevices(); }
    if (now - lastAHT >= AHT_READ_INTERVAL) { lastAHT = now; readAHT(); }
    if (now - lastOLED >= OLED_UPDATE_INTERVAL) {
      lastOLED = now;
      if (oledAutoRotate && now - lastOledRotate >= 5000) {
        lastOledRotate = now;
        oledPage = (oledPage + 1) % 7;
      }
      updateOLED();
    }
    delay(100);
  }
}

void TaskSMSCode(void *pvParameters) {
  unsigned long lastCheck = 0;
  unsigned long lastCleanup = 0;
  while (true) {
    unsigned long now = millis();
    if (now - lastCleanup > SMS_CLEANUP_INTERVAL) {
      lastCleanup = now;
      if (gsmReady && xSemaphoreTake(modemMutex, pdMS_TO_TICKS(10000)) == pdTRUE) {
        clearAllSMS();
        xSemaphoreGive(modemMutex);
      }
    }
    if (taskStatus.smsEnabled && !otaInProgress) {
      if (now - lastCheck >= SMS_CHECK_INTERVAL || forceRunSMS) {
        lastCheck = now;
        forceRunSMS = false;
        checkIncomingSMS();
      }
    }
    delay(500);
  }
}

void TaskLoggerCode(void *pvParameters) {
  unsigned long lastLog = 0;
  while (true) {
    if (taskStatus.logEnabled && sdReady && !otaInProgress) {
      if (millis() - lastLog >= logInterval || forceRunLog) {
        lastLog = millis();
        forceRunLog = false;
        logAllSensors();
      }
    }
    delay(1000);
  }
}

void TaskTimeCode(void *pvParameters) {
  unsigned long lastWiFi = 0, lastNTP = 0, lastSignal = 0, lastMonth = 0;
  while (true) {
    unsigned long now = millis();
    if (taskStatus.wifiEnabled && (now - lastWiFi >= WIFI_CHECK_INTERVAL || forceRunWiFi)) {
      lastWiFi = now;
      forceRunWiFi = false;
      if (WiFi.status() != WL_CONNECTED) {
        wifiConnected = false;
        WiFi.disconnect(); delay(100);
        WiFi.begin(wifiSSID, wifiPassword);
      } else if (!wifiConnected) {
        wifiConnected = true;
        if (taskStatus.ntpEnabled) syncTimeFromNTP();
        if (!mdnsRunning) setupMDNS();
      }
    }
    if (taskStatus.ntpEnabled && wifiConnected && (now - lastNTP >= NTP_SYNC_INTERVAL || forceRunNTP)) {
      lastNTP = now;
      forceRunNTP = false;
      syncTimeFromNTP();
    }
    if (now - lastSignal >= 60000) { lastSignal = now; updateGSMInfo(); }
    if (now - lastMonth >= MONTH_CHECK_INTERVAL) {
      lastMonth = now;
      if (timeReady) lastLogMonth = getShamsiDate().substring(0, 7);
    }
    delay(1000);
  }
}
