String pageFiles(String path) {
  String h = "<!DOCTYPE html><html><head><meta charset='UTF-8'><meta name='viewport' content='width=device-width,initial-scale=1'><title>Files</title>";
  h += getStyle();
  h += "</head><body><h1>📁 Files</h1>";
  h += getNav("files");
  h += "<div class='card'>📍 " + path + "</div>";
  h += "<div class='card'><h2>📄 فایل‌ها</h2>";
  File dir = SD.open(path);
  if (dir && dir.isDirectory()) {
    File f = dir.openNextFile();
    while (f) {
      String name = String(f.name());
      int ls = name.lastIndexOf('/');
      if (ls >= 0) name = name.substring(ls + 1);
      String fp = path;
      if (path != "/") fp += "/";
      fp += name;
          if (f.isDirectory()) {
        h += "<div>📁 <a href='/files?path=" + fp + "' style='color:#00d4ff'>" + name + "</a></div>";
      } else {
        h += "<div style='display:flex;justify-content:space-between;padding:5px'><span>📄 " + name + " (" + String(f.size()) + " B)</span>";
        h += "<span><a href='/download?file=" + fp + "' class='btn btn-green' style='padding:6px'>DL</a> ";
        h += "<a href='/delete?path=" + fp + "&back=" + path + "' class='btn btn-red' style='padding:6px' onclick='return confirm(\"حذف؟\")'>X</a></span></div>";
      }
      f = dir.openNextFile();
    }
    dir.close();
  }
  h += "</div></body></html>";
  return h;
}

