// ============================================================
// ========== SIM800 AT Terminal (Web) ============
// ============================================================
String atExplain(const String &r) {
  if (r.indexOf("+CBC:") >= 0) return "پاسخ باتری دریافت شد. قالب و اعتبار مقادیر به نسخه Firmware مودم وابسته است؛ مقدار ولتاژ معمولاً میلی‌ولت گزارش می‌شود.";
  if (r.indexOf("+CPIN: READY") >= 0) return "سیم‌کارت آماده است و PIN لازم ندارد.";
  if (r.indexOf("SIM not inserted") >= 0 || r.indexOf("SIM NOT INSERTED") >= 0) return "مودم سیم‌کارت را تشخیص نداده است؛ سیم‌کارت، خشاب و اتصالات را بررسی کنید.";
  if (r.indexOf("+CPIN: SIM PIN") >= 0) return "سیم‌کارت به PIN نیاز دارد. از وارد کردن PIN حدسی خودداری کنید.";
  if (r.indexOf("+CPIN: SIM PUK") >= 0) return "سیم‌کارت به PUK نیاز دارد؛ با اپراتور تماس بگیرید و PUK صحیح را دریافت کنید.";
  if (r.indexOf("+COPS:") >= 0) return "اطلاعات اپراتور انتخاب‌شده دریافت شد. کد/نام اپراتور را در پاسخ خام بررسی کنید.";
  if (r.indexOf("+CPMS:") >= 0) return "اطلاعات حافظه پیامک دریافت شد؛ ظرفیت کل و حافظه خالی را از پاسخ خام بخوانید.";
  if (r.indexOf("+CCLK:") >= 0) return "زمان مودم دریافت شد. منطقه زمانی و صحت ساعت را بررسی کنید؛ ممکن است زمان شبکه تنظیم نشده باشد.";
  if (r.indexOf("+CME ERROR: 10") >= 0) return "خطای سیم‌کارت: معمولاً SIM شناسایی نشده است.";
  if (r.indexOf("+CME ERROR: 11") >= 0) return "سیم‌کارت به PIN نیاز دارد.";
  if (r.indexOf("+CME ERROR: 12") >= 0) return "سیم‌کارت به PUK نیاز دارد.";
  if (r.indexOf("+CME ERROR: 13") >= 0) return "سیم‌کارت قفل شده؛ از تلاش مجدد با رمزهای حدسی پرهیز کنید.";
  if (r.indexOf("+CMS ERROR: 310") >= 0) return "خطای SMS: سیم‌کارت موجود نیست یا تشخیص داده نشده است.";
  if (r.indexOf("+CMS ERROR: 321") >= 0) return "خطای SMS: حافظه پیامک در دسترس نیست؛ حافظه و محل ذخیره را بررسی کنید.";
  if (r.indexOf("+CMS ERROR: 322") >= 0) return "خطای SMS: حافظه پیامک پر است؛ پیام‌های غیرضروری را از طریق روش امن پاک کنید.";
  if (r.indexOf("NO CARRIER") >= 0) return "حامل/ارتباط برقرار نشده یا قطع شده است؛ وضعیت شبکه و طرف ارتباط را بررسی کنید.";
  if (r.indexOf("NO ANSWER") >= 0) return "تماس بدون پاسخ پایان یافته است.";
  if (r.indexOf("BUSY") >= 0) return "خط یا مقصد مشغول گزارش شده است.";
  if (r.indexOf("+CGATT: 1") >= 0) return "اتصال GPRS برقرار گزارش شده است.";
  if (r.indexOf("+CGATT: 0") >= 0) return "اتصال GPRS برقرار نیست.";
  if (r.indexOf("+CPIN: READY") >= 0) return "سیم‌کارت آماده استفاده است.";
  if (r.indexOf("SIM PIN") >= 0) return "سیم‌کارت درخواست PIN دارد.";
  if (r.indexOf("SIM PUK") >= 0) return "سیم‌کارت قفل شده و PUK می‌خواهد.";
  if (r.indexOf("+CSQ:") >= 0) {
    int p = r.indexOf("+CSQ:"); int comma = r.indexOf(',', p);
    int q = comma > p ? r.substring(p + 5, comma).toInt() : 99;
    if (q == 99) return "قدرت سیگنال نامشخص است.";
    int dbm = -113 + 2 * q;
    String quality = q < 6 ? "بسیار ضعیف" : q < 10 ? "ضعیف" : q < 15 ? "متوسط" : q < 20 ? "خوب" : q < 26 ? "بسیار خوب" : "عالی";
    return "قدرت سیگنال: " + String(q) + "/31، حدود " + String(dbm) + " dBm؛ کیفیت " + quality + ".";
  }
  if (r.indexOf("+CREG:") >= 0) {
    int p = r.indexOf("+CREG:"); int c = r.indexOf(',', p); int st = c >= 0 ? r.substring(c+1).toInt() : -1;
    if (st == 1) return "ثبت در شبکه محلی انجام شده است.";
    if (st == 5) return "ثبت در شبکه رومینگ انجام شده است.";
    if (st == 2) return "مودم در حال جستجوی شبکه است.";
    if (st == 3) return "ثبت در شبکه رد شده است؛ سیم‌کارت، پوشش یا محدودیت اپراتور بررسی شود.";
    if (st == 0) return "مودم ثبت نشده و جستجوی شبکه انجام نمی‌دهد.";
    return "پاسخ وضعیت ثبت شبکه دریافت شد؛ جزئیات را بررسی کنید.";
  }
  if (r.indexOf("+CGATT: 1") >= 0) return "اتصال GPRS برقرار است.";
  if (r.indexOf("+CGATT: 0") >= 0) return "اتصال GPRS برقرار نیست.";
  if (r.indexOf("+CME ERROR") >= 0) return "خطای تجهیزات/شرایط اجرا (CME). متن خطا را بررسی کنید.";
  if (r.indexOf("+CMS ERROR") >= 0) return "خطای عملیات پیامک (CMS). متن یا کد خطا را بررسی کنید.";
  if (r.indexOf("ERROR") >= 0) return "دستور ناموفق یا نامعتبر است؛ دستور و وضعیت مودم را بررسی کنید.";
