  if (r.length() == 0) return "پاسخی دریافت نشد؛ مودم، UART، Baud و تغذیه را بررسی کنید.";
  return "پاسخ دریافت شد؛ برای این پاسخ تفسیر خودکار مشخصی نداریم.";
