void handleATPage() { server.send(200, "text/html; charset=utf-8", pageATTerminal()); }
void handleATCommand() {
  String cmd = server.arg("cmd"); cmd.trim();
  if (!cmd.length() || cmd.length() > 100 || cmd.indexOf('\r') >= 0 || cmd.indexOf('\n') >= 0 || cmd.indexOf(char(26)) >= 0) {
    server.send(400, "application/json", "{\"status\":\"دستور نامعتبر\",\"response\":\"\",\"interpretation\":\"فقط یک دستور کوتاه، بدون خط جدید یا Ctrl+Z مجاز است.\"}"); return;
  }
  // Multi-step/prompt-based commands are intentionally blocked in this basic terminal.
  String upper = cmd; upper.toUpperCase();
  if (upper.startsWith("AT+CMGS") || upper.startsWith("ATD") || upper == "ATA" || upper.startsWith("AT+CIPSEND") || upper.startsWith("AT+CPIN=")) {
    server.send(400, "application/json", "{\"status\":\"مسدود شد\",\"response\":\"\",\"interpretation\":\"این دستور مرحله‌ای یا حساس است و از ترمینال ساده اجرا نمی‌شود.\"}"); return;
  }
  if (xSemaphoreTake(modemMutex, pdMS_TO_TICKS(5000)) != pdTRUE) {
    server.send(503, "application/json", "{\"status\":\"مودم مشغول\",\"response\":\"\",\"interpretation\":\"Task پیامک/مودم مشغول است؛ کمی بعد دوباره تلاش کنید.\"}"); return;
  }
  modemFlush(); SerialAT.print(cmd); SerialAT.print("\r");
  String r; uint32_t start=millis(); bool finished=false;
  while (millis()-start < 6000) {
    while (SerialAT.available()) { char ch=(char)SerialAT.read(); r += ch; if (r.indexOf("\r\nOK\r\n")>=0 || r.endsWith("OK\r\n") || r.indexOf("ERROR")>=0 || r.indexOf("+CME ERROR")>=0 || r.indexOf("+CMS ERROR")>=0) finished=true; }
    if (finished) break; vTaskDelay(pdMS_TO_TICKS(5));
  }
  xSemaphoreGive(modemMutex);
  String status = finished ? (r.indexOf("ERROR")>=0 ? "پاسخ خطا" : "پاسخ دریافت شد") : "پایان مهلت انتظار";
  String interpret = atExplain(r);
  // Escape response strings for JSON.
  r.replace("\\", "\\\\"); r.replace("\"", "\\\""); r.replace("\r", "\\r"); r.replace("\n", "\\n");
  interpret.replace("\\", "\\\\"); interpret.replace("\"", "\\\""); interpret.replace("\r", "\\r"); interpret.replace("\n", "\\n");
  status.replace("\\", "\\\\"); status.replace("\"", "\\\"");
  server.send(200, "application/json; charset=utf-8", "{\"status\":\""+status+"\",\"response\":\""+r+"\",\"interpretation\":\""+interpret+"\"}");
}



