void handleServo360Turn() {
  float revs = server.arg("revs").toFloat();
  int speed = server.arg("speed").toInt();
  if (revs == 0) { server.send(200, "text/plain", "Revs != 0"); return; }
  if (abs(speed) < 10 || abs(speed) > 100) { server.send(200, "text/plain", "Speed 10-100"); return; }
  startServo360Turns(revs, speed);
  float oneRevS = SERVO360_FULL_REV_MS / 1000.0 / abs(speed) * 100.0 / turnCalibration;
  float totalS = oneRevS * abs(revs);
  server.send(200, "text/plain", "شروع: " + String(revs) + " دور در " + String(totalS, 1) + " ثانیه");
}

