// ===== Pump Handlers =====

void handlePumpOn() {
  int speed = server.arg("speed").toInt();
  if (speed <= 0 || speed > 100) { server.send(400, "text/plain", "Speed 1-100"); return; }
  pumpManualMode = true;
  pumpManualTimedActive = false;
  pumpOn(speed);
  server.send(200, "text/plain", "OK");
}

void handlePumpOff() {
  pumpOff();
  server.send(200, "text/plain", "OK");
}

void handlePumpRun() {
  int speed = server.arg("speed").toInt();
  int dur = server.arg("dur").toInt();
  if (speed <= 0 || speed > 100) { server.send(400, "text/plain", "Speed 1-100"); return; }
  if (dur <= 0 || dur > 3600) { server.send(400, "text/plain", "Duration 1-3600"); return; }
  pumpManualMode = false;
  pumpManualTimedStart(speed, dur);
  server.send(200, "text/plain", "OK");
}

void handlePumpTimerSave() {
  int slot = server.arg("slot").toInt();
  if (slot < 0 || slot >= MAX_PUMP_TIMERS) { server.send(400, "text/plain", "Invalid slot"); return; }
  bool en = server.arg("en").toInt() == 1;
  int h = server.arg("h").toInt();
  int m = server.arg("m").toInt();
  int dur = server.arg("dur").toInt();
  int spd = server.arg("spd").toInt();
  int rep = server.arg("rep").toInt();

  if (h < 0 || h > 23) { server.send(400, "text/plain", "Hour 0-23"); return; }
  if (m < 0 || m > 59) { server.send(400, "text/plain", "Minute 0-59"); return; }
  if (dur < 1 || dur > 3600) { server.send(400, "text/plain", "Duration 1-3600"); return; }
  if (spd < 1 || spd > 100) { server.send(400, "text/plain", "Speed 1-100"); return; }

  pumpTimers[slot].enabled = en;
  pumpTimers[slot].startHour = h;
  pumpTimers[slot].startMinute = m;
  pumpTimers[slot].durationSec = dur;
  pumpTimers[slot].speed = spd;
  pumpTimers[slot].repeatMode = (rep == 1) ? PUMP_REPEAT_DAILY : PUMP_REPEAT_ONCE;
  pumpTimers[slot].source = PUMP_SRC_WEB;
  pumpTimers[slot].executedToday = false;
  pumpTimers[slot].lastExecDayKey = -1;
  savePumpTimers();

  String info = "Timer #" + String(slot + 1) + " saved (WEB)";
  server.send(200, "text/plain", info);
}

void handlePumpTimerDel() {
  int slot = server.arg("slot").toInt();
  if (slot < 0 || slot >= MAX_PUMP_TIMERS) { server.send(400, "text/plain", "Invalid slot"); return; }
  if (pumpTimers[slot].isRunning) {
    pumpTimers[slot].isRunning = false;
    pumpOff();
  }
  pumpTimers[slot].enabled = false;
  pumpTimers[slot].source = PUMP_SRC_NONE;
  pumpTimers[slot].durationSec = 0;
  pumpTimers[slot].speed = 0;
  savePumpTimers();
  server.send(200, "text/plain", "Timer #" + String(slot + 1) + " deleted");
}

void handlePumpClear() {
  for (int i = 0; i < MAX_PUMP_TIMERS; i++) {
    pumpTimers[i].enabled = false;
    pumpTimers[i].source = PUMP_SRC_NONE;
    pumpTimers[i].isRunning = false;
    pumpTimers[i].durationSec = 0;
    pumpTimers[i].speed = 0;
  }
  pumpOff();
  savePumpTimers();
  server.send(200, "text/plain", "All timers cleared");
}

void handlePumpSaveEn() {
  int v = server.arg("v").toInt();
  pumpTimersSaveEnabled = (v == 1);
  savePumpTimers();
  server.send(200, "text/plain", pumpTimersSaveEnabled ? "Save: ON" : "Save: OFF");
}

