void handleTareSimple() {
  if (!hx711Ready) { server.send(500, "text/plain", "HX711 not ready"); return; }
  long sum = 0;
  for (int i = 0; i < 20; i++) { sum += scale.read(); delay(50); }
  hx711Offset = sum / 20;
  scale.set_offset(hx711Offset);
  saveSettings();
  resetWeightFilter();
  server.sendHeader("Location", "/weight");
  server.send(302, "text/plain", "OK");
}

void handleTareWeight() {
  float tg = server.arg("weight").toFloat();
  if (tg == 0) { server.send(400, "text/plain", "Invalid"); return; }
  long sum = 0;
  for (int i = 0; i < 20; i++) { sum += scale.read(); delay(50); }
  hx711Offset = (sum / 20) - (long)(tg * hx711Factor);
  scale.set_offset(hx711Offset);
  saveSettings();
  resetWeightFilter();
  server.sendHeader("Location", "/weight");
  server.send(302, "text/plain", "OK");
}

void handleCalibrate() {
  float kg = server.arg("known").toFloat();
  if (kg == 0) { server.send(400, "text/plain", "Invalid"); return; }
  long sum = 0;
  for (int i = 0; i < 20; i++) { sum += scale.read(); delay(50); }
  long raw = sum / 20;
  float diff = (float)(raw - hx711Offset);
  if (abs(diff) < 100) { server.send(400, "text/plain", "Too small"); return; }
  hx711Factor = diff / kg;
  scale.set_scale(hx711Factor);
  saveSettings();
  resetWeightFilter();
  server.sendHeader("Location", "/weight");
  server.send(302, "text/plain", "OK");
}

