// ========== Setup ============
// ============================================================

void setup() {
  Serial.begin(115200);
  delay(1000);
  bootTime = millis();

  Serial.println("========================================");
  Serial.println("ESP32-S3 Datalogger v10.7");
  Serial.println("+ Dual Servo + mDNS + JDN Settime");
  Serial.println("+ PUMP R385 + 10 Timers");
  Serial.println("========================================");

  // Semaphores
  modemMutex = xSemaphoreCreateMutex();
  sensorMutex = xSemaphoreCreateMutex();
  sdMutex = xSemaphoreCreateMutex();
  i2cMutex = xSemaphoreCreateMutex();
  servoMutex = xSemaphoreCreateMutex();
  servo360Mutex = xSemaphoreCreateMutex();
  pumpMutex = xSemaphoreCreateMutex();

  // LED
  pixels.begin();
  pixels.setBrightness(255);
  led(0, 0, 0);
  led(0, 0, 50);

  // Settings
  loadSettings();
  logMsg("Settings loaded");
  logMsg("Log interval: " + String(logInterval / 1000) + "s");
  logMsg("mDNS: " + String(mdnsName));

  // Pump Timers (init + load)
  pumpInitAllTimers();
  loadPumpTimers();
  logMsg("Pump timers loaded");

  // Hardware
  setupSD();
  setupI2C();
  setupSensors();
  setupServo();
  setupServo360();
  setupPump();

  // CSV
  if (!SD.exists(LOG_FILE)) createLogHeader();
  else refreshLogHeader();

  // Network
  connectWiFi();
  setupMDNS();
  setupWeb();
  setupOTA();

  // Time
  if (wifiConnected && taskStatus.ntpEnabled) syncTimeFromNTP();

  // SIM800
  initModem();
  if (!timeReady && taskStatus.simTimeEnabled) syncTimeFromSIM800();

  Serial.println("Free Heap: " + String(ESP.getFreeHeap()));

  // Tasks
  BaseType_t r;
  r = xTaskCreatePinnedToCore(TaskWebCode, "TaskWeb", 10240, NULL, 2, &TaskWeb, 0);
  Serial.println("TaskWeb: " + String(r == pdPASS ? "OK" : "FAIL"));

  r = xTaskCreatePinnedToCore(TaskLEDCode, "TaskLED", 2048, NULL, 1, &TaskLED, 0);
  Serial.println("TaskLED: " + String(r == pdPASS ? "OK" : "FAIL"));

  r = xTaskCreatePinnedToCore(TaskSensorsCode, "TaskSensors", 4096, NULL, 2, &TaskSensors, 1);
  Serial.println("TaskSensors: " + String(r == pdPASS ? "OK" : "FAIL"));

  r = xTaskCreatePinnedToCore(TaskI2CCode, "TaskI2C", 4096, NULL, 1, &TaskI2C, 1);
  Serial.println("TaskI2C: " + String(r == pdPASS ? "OK" : "FAIL"));

  r = xTaskCreatePinnedToCore(TaskServo360Code, "TaskServo360", 2048, NULL, 1, &TaskServo360, 1);
  Serial.println("TaskServo360: " + String(r == pdPASS ? "OK" : "FAIL"));

  r = xTaskCreatePinnedToCore(TaskPumpCode, "TaskPump", 4096, NULL, 2, &TaskPump, 1);
  Serial.println("TaskPump: " + String(r == pdPASS ? "OK" : "FAIL"));

  r = xTaskCreatePinnedToCore(TaskSMSCode, "TaskSMS", 6144, NULL, 2, &TaskSMS, 1);
  Serial.println("TaskSMS: " + String(r == pdPASS ? "OK" : "FAIL"));

  r = xTaskCreatePinnedToCore(TaskLoggerCode, "TaskLogger", 6144, NULL, 1, &TaskLogger, 1);
  Serial.println("TaskLogger: " + String(r == pdPASS ? "OK" : "FAIL"));

  r = xTaskCreatePinnedToCore(TaskTimeCode, "TaskTime", 6144, NULL, 1, &TaskTime, 1);
  Serial.println("TaskTime: " + String(r == pdPASS ? "OK" : "FAIL"));

  delay(200);
  Serial.println("Free Heap after tasks: " + String(ESP.getFreeHeap()));

  led(0, 50, 0);
  logMsg("SYSTEM READY v10.7");

  // Startup SMS
  if (gsmReady && gsmRegistered) {
    delay(2000);
    String msg = "ESP32 v10.7 Started\n";
    msg += getFormattedTimeResponse() + "\n";
    msg += "W: " + formatWeight(currentWeightGrams) + "\n";
    msg += "Pump: " + String(pumpCurrentSpeed) + "%\n";
    msg += "Log: " + String(logInterval / 1000) + "s\n";
    msg += "mDNS: http://" + String(mdnsName) + ".local\n";
    msg += "IP: " + WiFi.localIP().toString();
    sendSMS(authorizedNumber, msg);
  }

  Serial.println("========================================");
  Serial.println("SETUP COMPLETE v10.7");
  Serial.println("========================================");
}

void loop() {
  delay(1000);
}
